use std::io::{self, Write};

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        writeln!(io::stdout(), "Enter an argument. Example 1234 or dcba:")?;
        return Ok(());
    }

    let mut chars: Vec<char> = args[1].chars().collect();
    chars.sort_unstable();

    let mut a = chars.clone();
    let mut fact = 1;
    for k in 0..a.len() {
        fact *= k + 1;
    }

    let mut y = 0;
    while y != fact {
        println!("{}", a.iter().collect::<String>());
        let mut i = a.len() as isize - 2;
        while i >= 0 && a[i as usize] >= a[(i + 1) as usize] {
            i -= 1;
        }
        if i >= 0 {
            let mut j = a.len() as isize - 1;
            while a[j as usize] <= a[i as usize] {
                j -= 1;
            }
            a.swap(i as usize, j as usize);
        }
        i += 1;
        let mut j = a.len() as isize - 1;
        while i < j {
            a.swap(i as usize, j as usize);
            i += 1;
            j -= 1;
        }
        y += 1;
    }

    Ok(())
}

