use std::f64::INFINITY;

const C: f64 = 7.0;

#[derive(Debug, Clone, Copy)]
struct Pt {
    x: f64,
    y: f64,
}

impl Pt {
    fn zero() -> Self {
        Pt { x: INFINITY, y: INFINITY }
    }

    fn is_zero(&self) -> bool {
        self.x > 1e20 || self.x < -1e20
    }

    fn neg(&self) -> Self {
        Pt { x: self.x, y: -self.y }
    }

    fn dbl(&self) -> Self {
        if self.is_zero() {
            return *self;
        }

        let l = (3.0 * self.x * self.x) / (2.0 * self.y);
        Pt {
            x: l * l - 2.0 * self.x,
            y: l * (self.x - l) - self.y,
        }
    }

    fn add(&self, other: &Self) -> Self {
        if self.x == other.x && self.y == other.y {
            return self.dbl();
        }
        if self.is_zero() {
            return *other;
        }
        if other.is_zero() {
            return *self;
        }

        let l = (other.y - self.y) / (other.x - self.x);
        Pt {
            x: l * l - self.x - other.x,
            y: l * (self.x - l) - self.y,
        }
    }

    fn mul(&self, n: i32) -> Self {
        let mut r = Pt::zero();
        let mut p = *self;
        let mut i = 1;

        while i <= n {
            if i & n != 0 {
                r = r.add(&p);
            }
            p = p.dbl();
            i <<= 1;
        }
        r
    }

    fn show(&self, label: &str) {
        println!(
            "{}{}",
            label,
            if self.is_zero() {
                "Zero".to_string()
            } else {
                format!("({:.3}, {:.3})", self.x, self.y)
            }
        );
    }

    fn from_y(y: f64) -> Self {
        Pt {
            x: (y * y - C).cbrt(),
            y,
        }
    }
}

