        match c {
            '0'..='9' => {
                if i < 2 {
                    return false;
                }
                s.push(c.to_digit(10).unwrap() as i32);
            }
            'A'..='Z' => {
                if i == 11 {
                    return false;
                }
                let k = c as i32 - 'A' as i32 + 10;
                s.push(k / 10);
                s.push(k % 10);
            }
            _ => return false,
        }
    }

    let mut v = 0;
    for i in (0..s.len()).rev().step_by(2) {
        let k = 2 * s[i];
        v += if k > 9 { k - 9 } else { k };
    }

    for i in (1..s.len()).rev().step_by(2) {
        v += s[i];
    }

    v % 10 == 0
}

