            write!(buffer, "{}", (b'a' + (q - 10) as u8) as char).unwrap();
        }
        n -= q * div;
    }
    print!("{}", buffer);
}

fn main() {
    let mut cnt = 0;
    let base = 10;

    println!("base 10:");
    for i in 1..1_000_000 {
        if kaprekar(i, base) != 0 {
            cnt += 1;
            println!("{:3}: {}", cnt, i);
        }
    }

    let base = 17;
    println!("\nbase {}:\n  1: 1", base);
    cnt = 1;
    for i in 2..1_000_000 {
        if let tens @ 1.. = kaprekar(i, base) {
            cnt += 1;
            print!("{:3}: {}", cnt, i);
            print!("\t");
            print_num(i, base);
            print!("\t");
            print_num(i * i, base);
            print!("\t");
            print_num(i * i / tens, base);
            print!(" + ");
            print_num(i * i % tens, base);
            println!();
        }
    }
}

