fn valid(n: i32, mut nuts: i32) -> bool {
    for k in (1..=n).rev() {
        if nuts % n != 1 {
            return false;
        }
        nuts -= 1 + nuts / n;
    }
    nuts > 0 && nuts % n == 0
}

