                let k = c as i32 - 'A' as i32 + 10;
                s.push(k / 10);
                s.push(k % 10);
            }
            _ => return false,
        }
    }

    let mut v = 0;
    for i in (0..s.len()).rev().step_by(2) {
        let k = 2 * s[i];
        v += if k > 9 { k - 9 } else { k };
    }

    for i in (1..s.len()).rev().step_by(2) {
        v += s[i];
    }

    v % 10 == 0
}

