fn digsum(mut n: i32) -> i32 {
    let mut sum = 0;
    while n != 0 {
        sum += n % 10;
        n /= 10;
    }
    sum
}

fn main() {
    let mut n = 1;
    let mut found = 0;
    loop {
        if n % digsum(n) == 0 {
            if found < 20 {
                print!("{} ", n);
            }
