fn hailstone(n: u32) -> (usize, Vec<u32>) {
    let mut hs = 1;
    let mut arry = Vec::new();
    let mut current = n;

    while current != 1 {
        hs += 1;
        arry.push(current);
        current = if current % 2 == 1 { 3 * current + 1 } else { current / 2 };
    }
    arry.push(current);

    (hs, arry)
}

fn main() {
    let mut hmax = 0;
    let mut jatmax = 0;

    for j in 1..100000 {
        let (n, _) = hailstone(j);
        if hmax < n {
            hmax = n;
            jatmax = j;
        }
    }

    let (n, arry) = hailstone(27);

    println!(
        "[ {}, {}, {}, {} ...., {}, {}, {}, {}] len={}",
        arry[0], arry[1], arry[2], arry[3],
        arry[n - 4], arry[n - 3], arry[n - 2], arry[n - 1], n
    );
    println!("Max {} at j= {}", hmax, jatmax);
}

