        a.sort();
        println!("Sorted list: {:?}", a);
        let sum = a[0] + a[1];
        println!("Two smallest: {} + {} = {}", a[0], a[1], sum);
        a.drain(0..2);
        a.push(sum);
        a.sort(); // Re-sort after adding the new sum
    }
    println!("Last item is {}.", a[0]);
}

