const MOD: u32 = 1_000_000_000;

struct Subrand {
    state: [u32; 55],
    si: usize,
    sj: usize,
}

impl Subrand {
    fn new() -> Self {
        Subrand {
            state: [0; 55],
            si: 0,
            sj: 0,
        }
    }

    fn seed(&mut self, mut p1: u32) {
        self.state[0] = p1 % MOD;
        let mut p2 = 1;
        for (i, j) in (1..55).zip((21..).cycle().take(54)) {
            self.state[j] = p2;
            p2 = if p1 >= p2 { p1 - p2 } else { MOD + p1 - p2 };
            p1 = self.state[j];
        }
        self.si = 0;
        self.sj = 24;
        for _ in 0..165 {
            self.subrand();
        }
    }

    fn subrand(&mut self) -> u32 {
        if self.si == self.sj {
            self.seed(0);
        }

        self.si = if self.si == 0 { 54 } else { self.si - 1 };
        self.sj = if self.sj == 0 { 54 } else { self.sj - 1 };
        let x = if self.state[self.si] >= self.state[self.sj] {
            self.state[self.si] - self.state[self.sj]
        } else {
            MOD + self.state[self.si] - self.state[self.sj]
        };

        self.state[self.si] = x;
        x
    }
}

fn main() {
    let mut rng = Subrand::new();
    rng.seed(292929);
    for _ in 0..10 {
        println!("{}", rng.subrand());
    }
}

