#include <stdio.h>

int valid(int n, int nuts)
{
	int k;
	for (k = n; k; k--, nuts -= 1 + nuts/n)
		if (nuts%n != 1) return 0;
	return nuts && !(nuts%n);
}

int main(void)
{
	int n, x;
	for (n = 2; n < 10; n++) {
		for (x = 0; !valid(n, x); x++);
		printf("%d: %d\n", n, x);
	}
	return 0;
}

8fdaeb19cd1558cad288649b41472610.rust_code:
fn valid(n: i32, mut nuts: i32) -> bool {
    for k in (1..=n).rev() {
        if nuts % n != 1 {
            return false;
        }
        nuts -= 1 + nuts / n;
    }
    nuts > 0 && nuts % n == 0
}

fn main() {
    for n in 2..10 {
        let mut x = 0;
        while !valid(n, x) {
            x += 1;
        }
        println!("{}: {}", n, x);
    }
}

