use std::env;

fn type_detector(c: char) {
    if c.is_alphanumeric() {
        println!("\n{} is alphanumeric", c);
    }
    if c.is_alphabetic() {
        println!("\n{} is alphabetic", c);
    }
    if c.is_control() {
        println!("\n{} is a control character", c);
    }
    if c.is_digit(10) {
        println!("\n{} is a digit", c);
    }
    if c.is_ascii_graphic() || c == ' ' {
        println!("\n{} is printable", c);
    }
    if c.is_ascii_punctuation() {
        println!("\n{} is a punctuation character", c);
    }
    if c.is_ascii_hexdigit() {
        println!("\n{} is a hexadecimal digit", c);
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() == 1 {
        println!("Usage: {} <followed by ASCII characters>", args[0]);
    } else {
        for arg in &args[1..] {
            if let Some(c) = arg.chars().next() {
                type_detector(c);
            }
        }
    }
}

