fn valid(n: i32, mut nuts: i32) -> bool {
    for k in (1..=n).rev() {
        if nuts % n != 1 {
            return false;
        }
        nuts -= 1 + nuts / n;
    }
    nuts > 0 && nuts % n == 0
}

fn main() {
    for n in 2..10 {
        let mut x = 0;
        while !valid(n, x) {
            x += 1;
        }
        println!("{}: {}", n, x);
    }
}

