    let mut num = 0;
    for &digit in results.iter().take_while(|&&c| c != 0) {
        num = 3 * num + (digit - b'0') as i32;
    }

    num += 1;

    let mut ptr = 5;
    while num > 0 {
        let rem = num % 3;
        num /= 3;
        results[ptr] = (rem as u8) + b'0';
        if ptr == 0 {
