fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 {
        process::exit(1);
    }

    let b: i32 = match args[args.len() - 1].parse() {
        Ok(val) => val,
        Err(_) => process::exit(2),
    };
    if b == 0 {
