#include <stdio.h>
#include <stdlib.h>

float epsilon() {
    float eps = 1.0f;
    while (1.0f + eps != 1.0f) eps /= 2.0f;
    return eps;
}

float kahanSum(float *nums, int count) {
    float sum = 0.0f;
    float c = 0.0f;
    float t, y;
    int i;
    for (i = 0; i < count; ++i) {
        y = nums[i] - c;
        t = sum + y;
        c = (t - sum) - y;
        sum = t;
    }
    return sum;
}

int main() {
    float a = 1.0f;
    float b = epsilon();
    float c = -b;
    float fa[3];

    fa[0] = a;
    fa[1] = b;
    fa[2] = c;

    printf("Epsilon     = %0.12f\n", b);
    printf("(a + b) + c = %0.12f\n", (a + b) + c);
    printf("Kahan sum   = %0.12f\n", kahanSum(fa, 3));

    return 0;
}

5212ede21205b34a1860bf5d2bed6f2e.rust_code:
fn epsilon() -> f32 {
    let mut eps = 1.0f32;
    while 1.0f32 + eps != 1.0f32 {
        eps /= 2.0f32;
    }
    eps
}

fn kahan_sum(nums: &[f32]) -> f32 {
    let mut sum = 0.0f32;
    let mut c = 0.0f32;
    for &num in nums {
        let y = num - c;
        let t = sum + y;
        c = (t - sum) - y;
        sum = t;
    }
    sum
}

fn main() {
    let a = 1.0f32;
    let b = epsilon();
    let c = -b;
    let fa = [a, b, c];

    println!("Epsilon     = {:0.12}", b);
    println!("(a + b) + c = {:0.12}", (a + b) + c);
    println!("Kahan sum   = {:0.12}", kahan_sum(&fa));
}

