#define _CRT_SECURE_NO_WARNINGS 

#include <stdio.h>
#include <stdlib.h>


char* seconds2string(unsigned long seconds) 
{
    int i;

    const unsigned long s =  1;
    const unsigned long m = 60 * s;
    const unsigned long h = 60 * m;
    const unsigned long d = 24 * h;
    const unsigned long w =  7 * d;

    const unsigned long coeff[5] = { w, d, h, m, s };
    const char units[5][4] = { "wk", "d", "hr", "min", "sec" };

    static char buffer[256];
    char* ptr = buffer;

    for ( i = 0; i < 5; i++ )
    {
        unsigned long value;
        value   = seconds / coeff[i];
        seconds = seconds % coeff[i];
        if ( value )
        {
            if ( ptr != buffer ) 
                ptr += sprintf(ptr, ", ");
            ptr += sprintf(ptr,"%lu %s",value,units[i]);
        }
    }

    return buffer;
}


int main(int argc, char argv[])
{
    unsigned long seconds;

    if ( (argc <  2) && scanf( "%lu", &seconds ) 
    ||   (argc >= 2) && sscanf( argv[1], "%lu", & seconds ) )
    {
        printf( "%s\n", seconds2string(seconds) );
        return EXIT_SUCCESS;
    }

    return EXIT_FAILURE;
}

6ecc46bce834a58c7bcf45a33db42d4d.rust_code:
use std::fmt::Write;

fn seconds2string(seconds: u64) -> String {
    let coeffs = [604800, 86400, 3600, 60, 1];
    let units = ["wk", "d", "hr", "min", "sec"];

    let mut buffer = String::new();
    let mut remaining_seconds = seconds;
    let mut first = true;

    for (&coeff, &unit) in coeffs.iter().zip(units.iter()) {
        let value = remaining_seconds / coeff;
        remaining_seconds %= coeff;
        if value > 0 {
            if !first {
                write!(buffer, ", ").unwrap();
            }
            write!(buffer, "{} {}", value, unit).unwrap();
            first = false;
        }
    }

    buffer
}

fn main() {
    use std::env;

    let args: Vec<String> = env::args().collect();
    let seconds: u64 = match args.len() {
        1 => {
            let mut input = String::new();
            std::io::stdin().read_line(&mut input).expect("Failed to read line");
            input.trim().parse().expect("Please type a number!")
        },
        _ => args[1].parse().expect("Please provide a valid number as an argument!"),
    };

    println!("{}", seconds2string(seconds));
}

