    offset: [Uint; 33],
}

impl TreeList {
    fn new() -> Self {
        TreeList {
            list: Vec::new(),
            offset: [0; 33],
        }
    }

    fn append(&mut self, t: Tree) {
        self.list.push(1 | t << 1);
    }

    fn show(&self, mut t: Tree, len: Uint) {
        for _ in 0..len {
            print!("{}", if t & 1 == 1 { '(' } else { ')' });
            t >>= 1;
        }
    }

    fn list_trees(&self, n: Uint) {
        for &item in &self.list[self.offset[n as usize] as usize..self.offset[(n + 1) as usize] as usize] {
            self.show(item, n * 2);
            println!();
        }
    }

    fn assemble(&mut self, n: Uint, mut t: Tree, mut sl: Uint, mut pos: Uint, rem: Uint) {
        if rem == 0 {
            self.append(t);
            return;
        }

        if sl > rem {
            pos = self.offset[rem as usize];
        } else if pos >= self.offset[(sl + 1) as usize] {
            if sl == 0 {
                return;
            }
            sl -= 1;
            pos = self.offset[sl as usize];
        }

        self.assemble(n, t << (2 * sl) | self.list[pos as usize], sl, pos, rem - sl);
        self.assemble(n, t, sl, pos + 1, rem);
    }

    fn mktrees(&mut self, n: Uint) {
        if self.offset[(n + 1) as usize] != 0 {
            return;
        }
        if n != 0 {
            self.mktrees(n - 1);
        }

        self.assemble(n, 0, n - 1, self.offset[(n - 1) as usize], n - 1);
        self.offset[(n + 1) as usize] = self.list.len() as Uint;
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let n: Uint = args.get(1).and_then(|s| s.parse().ok()).unwrap_or(5).clamp(1, 25);

    let mut tree_list = TreeList::new();
    tree_list.append(0);

    tree_list.mktrees(n);
    eprintln!("Number of {}-trees: {}", n, tree_list.offset[(n + 1) as usize] - tree_list.offset[n as usize]);
    tree_list.list_trees(n);
}

