fn same_digits(mut n: i32, b: i32) -> bool {
    let f = n % b;
    n /= b;
    while n > 0 {
        if n % b != f {
            return false;
        }
        n /= b;
    }
    true
}

fn is_brazilian(n: i32) -> bool {
    if n < 7 {
        return false;
    }
    if n % 2 == 0 && n >= 8 {
        return true;
    }
    for b in 2..n - 1 {
        if same_digits(n, b) {
            return true;
        }
    }
    false
}

fn is_prime(n: i32) -> bool {
    if n < 2 {
        return false;
    }
    if n % 2 == 0 {
        return n == 2;
    }
    if n % 3 == 0 {
        return n == 3;
    }
    let mut d = 5;
    while d * d <= n {
        if n % d == 0 {
            return false;
        }
        d += 2;
        if n % d == 0 {
            return false;
        }
        d += 4;
    }
    true
}

fn main() {
    let kinds = ["", " odd ", " prime "];
    for &kind in &kinds {
        println!("First 20{}Brazilian numbers:", kind);
        let mut count = 0;
        let mut n = 7;
        loop {
            if is_brazilian(n) {
                print!("{} ", n);
                count += 1;
                if count == 20 {
                    println!();
                    println!();
                    break;
                }
            }
            match kind {
                "" => n += 1,
                " odd " => n += 2,
                " prime " => {
                    loop {
                        n += 2;
                        if is_prime(n) {
                            break;
                        }
                    }
                }
                _ => unreachable!(),
            }
        }
    }

    let mut count = 0;
    let mut n = 7;
    while count < 100000 {
        if is_brazilian(n) {
            count += 1;
        }
        n += 1;
    }
    println!("The 100,000th Brazilian number: {}", n - 1);
}

