use std::fmt;

fn show(grid: &[u8; 81]) {
    for (i, &value) in grid.iter().enumerate() {
        if i % 9 == 0 {
            println!();
        }
        if i % 3 == 0 {
            print!(" ");
        }
        print!("{:2}", value);
    }
    println!();
}

fn try_cell(grid: &mut [u8; 81], pos: usize) -> bool {
    if pos == 81 {
        return true;
    }
    if grid[pos] != 0 {
        return try_cell(grid, pos + 1);
    }

    let mut used = 0;
    let row = pos / 9;
    let col = pos % 9;

    for i in 0..9 {
        used |= 1 << (grid[i * 9 + col] - 1);
    }

    for j in 0..9 {
        used |= 1 << (grid[row * 9 + j] - 1);
    }

    let box_row = (row / 3) * 3;
    let box_col = (col / 3) * 3;
    for i in box_row..box_row + 3 {
        for j in box_col..box_col + 3 {
            used |= 1 << (grid[i * 9 + j] - 1);
        }
    }

    for num in 1..=9 {
        if used & (1 << (num - 1)) == 0 {
            grid[pos] = num;
            if try_cell(grid, pos + 1) {
                return true;
            }
        }
    }

    grid[pos] = 0;
    false
}

fn solve(s: &str) {
    let mut grid = [0; 81];
    for (i, c) in s.chars().filter(|&c| !c.is_whitespace()).enumerate() {
        grid[i] = if c >= '1' && c <= '9' { c as u8 - b'0' } else { 0 };
    }

    if try_cell(&mut grid, 0) {
        show(&grid);
    } else {
        println!("no solution");
    }
}

