    let mut tens = 1;

    if (nn - n) % (base as u64 - 1) != 0 {
        return 0;
    }

    while tens < n {
        tens *= base as u64;
    }
    if n == tens {
        return if n == 1 { 1 } else { 0 };
    }

    while let r @ 0.. = nn % tens {
        if nn / tens + r == n {
            return tens;
        }
        tens *= base as u64;
    }

