#include <stdio.h>
#include <string.h>

int digitSum(int n) {
    int s = 0;
    do {s += n % 10;} while (n /= 10);
    return s;
}

int digitSumIsSubstring(int n) {
    char s_n[32], s_ds[32];
    sprintf(s_n, "%d", n);
    sprintf(s_ds, "%d", digitSum(n));
    return strstr(s_n, s_ds) != NULL;
}

int main() {
    int i;
    for (i=0; i<1000; i++)
        if (digitSumIsSubstring(i))
            printf("%d ",i);
    printf("\n");

    return 0;
}

bd8ef22d13c6cacd8261d988fb4e9b21.rust_code:
fn digit_sum(mut n: i32) -> i32 {
    let mut s = 0;
    while n > 0 {
        s += n % 10;
        n /= 10;
    }
    s
}

fn digit_sum_is_substring(n: i32) -> bool {
    let s_n = n.to_string();
    let s_ds = digit_sum(n).to_string();
    s_n.contains(&s_ds)
}

fn main() {
    for i in 0..1000 {
        if digit_sum_is_substring(i) {
            print!("{} ", i);
        }
    }
    println!();
}

