fn vc(n: i32, base: i32) -> (i32, i32) {
    let mut p = 0;
    let mut q = 1;
    let mut num = n;

    while num != 0 {
        p = p * base + (num % base);
        q *= base;
        num /= base;
    }

    let mut gcd = |mut a: i32, mut b: i32| -> i32 {
        while b != 0 {
            let temp = b;
            b = a % b;
            a = temp;
        }
        a
    };

    let divisor = gcd(p, q);
    (p / divisor, q / divisor)
}

fn main() {
    for base in 2..6 {
        print!("base {}: ", base);
        for i in 0..10 {
            let (num, denom) = vc(i, base);
            if num != 0 {
                print!("  {}/{}", num, denom);
            } else {
                print!("  0");
            }
        }
        println!();
    }
}

