use std::fmt::Write;

fn kaprekar(n: u64, base: i32) -> u64 {
    let nn = n * n;
    let mut tens = 1;

    if (nn - n) % (base as u64 - 1) != 0 {
        return 0;
    }

    while tens < n {
        tens *= base as u64;
    }
    if n == tens {
        return if n == 1 { 1 } else { 0 };
    }

    while let r @ 0.. = nn % tens {
        if nn / tens + r == n {
            return tens;
        }
        tens *= base as u64;
    }

    0
}

fn print_num(mut n: u64, base: i32) {
    let mut div = base as u64;
    while div < n {
        div *= base as u64;
    }
    let mut buffer = String::new();
    while n > 0 && div > 1 {
        div /= base as u64;
        let q = n / div;
        if q < 10 {
            write!(buffer, "{}", q).unwrap();
        } else {
            write!(buffer, "{}", (b'a' + (q - 10) as u8) as char).unwrap();
        }
        n -= q * div;
    }
    print!("{}", buffer);
}

