fn main() {
    let arr = [0, 2, 11, 19, 90];
    let sum = 21;
    let mut check = false;

    for (i, &val_i) in arr.iter().enumerate().take(4) {
        for (j, &val_j) in arr.iter().enumerate().skip(i + 1) {
            if val_i + val_j == sum {
                println!("[{},{}]", i, j);
                check = true;
                break;
            }
        }
        if check {
            break;
        }
    }

    if !check {
        println!("[]");
    }
}

