#include <stdio.h>
#include <stdlib.h>
#include <math.h>
int main(void) {
    int nprimes =  1000000;
    int nmax =    ceil(nprimes*(log(nprimes)+log(log(nprimes))-0.9385));  


    int i, j, m, k; int *a;
    k = (nmax-2)/2; 
    a = (int *)calloc(k + 1, sizeof(int));
    for(i = 0; i <= k; i++)a[i] = 2*i+1; 
    for (i = 1; (i+1)*i*2 <= k; i++)
        for (j = i; j <= (k-i)/(2*i+1); j++) {
            m = i + j + 2*i*j;
            if(a[m]) a[m] = 0;
            }            

    for (i = 1, j = 0; i <= k; i++) 
       if (a[i]) {
           if(j%10 == 0 && j <= 100)printf("\n");
           j++; 
           if(j <= 100)printf("%3d ", a[i]);
           else if(j == nprimes){
               printf("\n%d th prime is %d\n",j,a[i]);
               break;
               }
           }
}

f8d0297ceaa1680de0b640c3b20f609c.rust_code:
use std::f64;

fn main() {
    let nprimes = 1_000_000;
    let nmax = (nprimes as f64 * (f64::ln(nprimes as f64) + f64::ln(f64::ln(nprimes as f64)) - 0.9385)).ceil() as usize;

    let mut a = vec![0; (nmax - 2) / 2];
    for (i, val) in a.iter_mut().enumerate() {
        *val = 2 * i + 1;
    }

    for i in 1..=((nmax as f64).sqrt() as usize / 2) {
        for j in i..=((nmax - 2 * i * i - 2 * i) / (2 * i + 1)) {
            let m = i + j + 2 * i * j;
            if m < a.len() {
                a[m] = 0;
            }
        }
    }

    let mut count = 0;
    for &prime in &a {
        if prime != 0 {
            if count % 10 == 0 && count <= 100 {
                println!();
            }
            count += 1;
            if count <= 100 {
                print!("{:3} ", prime);
            } else if count == nprimes {
                println!("\n{} th prime is {}", count, prime);
                break;
            }
        }
    }
}

