fn cmp(p: &[u8], q: &[u8]) -> bool {
    let mut iter_p = p.iter();
    let mut iter_q = q.iter();
    loop {
        match (iter_p.next(), iter_q.next()) {
            (Some(_), Some(_)) => continue,
            _ => return iter_p.next().is_some(),
        }
    }
}

