#include <stdio.h>

static int p[19] = {0, 0, 1, 1, 0, 1, 0, 1, 0, 0,
                    0, 1, 0, 1, 0, 0, 0, 1, 0};

int isstrange(long n) {
    if (n < 10) return 0;
    for (; n >= 10; n /= 10) {
        if (!p[n%10 + (n/10)%10]) return 0;
    }
    return 1;
}

int main(void) {
    long n;
    int k = 0;

    for (n = 101; n < 500; n++) {
        if (isstrange(n)) {
            printf("%d%c", n, ++k%10 ? ' ' : '\n');
        }
    }
    return 0;
}

6ee9136f5dbd15a04447ebf66ce620c2.rust_code:
fn is_strange(n: u64) -> bool {
    if n < 10 {
        return false;
    }
    let p = [0, 0, 1, 1, 0, 1, 0, 1, 0, 0, 0, 1, 0, 1, 0, 0, 0, 1, 0];
    let mut num = n;
    while num >= 10 {
        let digit_sum = (num % 10) + ((num / 10) % 10);
        if p[digit_sum as usize] == 0 {
            return false;
        }
        num /= 10;
    }
    true
}

fn main() {
    let mut k = 0;
    for n in 101..500 {
        if is_strange(n) {
            print!("{}{}", n, if (k + 1) % 10 == 0 { '\n' } else { ' ' });
            k += 1;
        }
    }
}

