fn cycle_sort(list: &mut [i32]) -> usize {
    let mut writes = 0;

    for cycle_start in 0..list.len() - 1 {
        let mut item = list[cycle_start];

        let mut pos = cycle_start;
        for &value in &list[cycle_start + 1..] {
            if value < item {
                pos += 1;
            }
        }

        if pos == cycle_start {
            continue;
        }

        while list[pos] == item {
            pos += 1;
        }
        list.swap(pos, cycle_start);
        item = list[pos];
        writes += 1;

        while pos != cycle_start {
            pos = cycle_start;
            for &value in &list[cycle_start + 1..] {
                if value < item {
                    pos += 1;
                }
            }

            while list[pos] == item {
                pos += 1;
            }
            list.swap(pos, cycle_start);
            item = list[pos];
            writes += 1;
        }
    }

    writes
}

