fn modpow(mut b: u32, mut e: u32, m: u32) -> u32 {
    let mut p = 1;
    while e > 0 {
        if e & 1 != 0 {
            p = p * b % m;
        }
        b = b * b % m;
        e >>= 1;
    }
    p
}

