#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int catcmp(const void *a, const void *b)
{
	char ab[32], ba[32];
	sprintf(ab, "%d%d", *(int*)a, *(int*)b);
	sprintf(ba, "%d%d", *(int*)b, *(int*)a);
	return strcmp(ba, ab);
}

void maxcat(int *a, int len)
{
	int i;
	qsort(a, len, sizeof(int), catcmp);
	for (i = 0; i < len; i++)
		printf("%d", a[i]);
	putchar('\n');
}

int main(void)
{
	int x[] = {1, 34, 3, 98, 9, 76, 45, 4};
	int y[] = {54, 546, 548, 60};

	maxcat(x, sizeof(x)/sizeof(x[0]));
	maxcat(y, sizeof(y)/sizeof(y[0]));

	return 0;
}

17e9c78c768a76d967e9944bd3657a23.rust_code:
use std::cmp::Ordering;

fn catcmp(a: &i32, b: &i32) -> Ordering {
    let ab = format!("{}{}", a, b);
    let ba = format!("{}{}", b, a);
    ba.cmp(&ab)
}

fn maxcat(mut a: Vec<i32>) {
    a.sort_by(catcmp);
    for num in a {
        print!("{}", num);
    }
    println!();
}

fn main() {
    let x = vec![1, 34, 3, 98, 9, 76, 45, 4];
    let y = vec![54, 546, 548, 60];

    maxcat(x);
    maxcat(y);
}

