use std::io::{self, Write};

fn main() {
    let mut current_average: f32 = 0.0;
    let mut current_entry_number: u32 = 0;

    loop {
        print!("Enter rainfall int, 99999 to quit: ");
        io::stdout().flush().unwrap();

        let mut input = String::new();
        if io::stdin().read_line(&mut input).is_err() {
            println!("Invalid input");
            continue;
        }

        match input.trim().parse::<i32>() {
            Ok(entry) => {
                if entry == 99999 {
                    println!("User requested quit.");
                    break;
                } else {
                    current_entry_number += 1;
                    current_average = current_average + (1.0 / current_entry_number as f32) * entry as f32 - (1.0 / current_entry_number as f32) * current_average;

                    println!("New Average: {}", current_average);
                }
            }
            Err(_) => {
                println!("Invalid input");
            }
        }
    }
}

