use std::collections::HashSet;

fn uniq(names: &mut [&str]) {
    let mut seen = HashSet::new();
    for name in names.iter_mut() {
        if !seen.insert(*name) {
            *name = "";
        }
    }
}

fn in_set(set: &[&str], match_name: &str) -> bool {
    set.iter().any(|&name| name == match_name)
}

fn show_diff(x: &[&str], y: &[&str]) {
    for &name in x {
        if !name.is_empty() && !in_set(y, name) {
            println!("  {}", name);
        }
    }
}

fn show_sym_diff(x: &[&str], y: &[&str]) {
    show_diff(x, y);
    show_diff(y, x);
}

fn main() {
    let mut a = ["John", "Serena", "Bob", "Mary", "Serena"];
    let mut b = ["Jim", "Mary", "John", "Jim", "Bob"];

    uniq(&mut a);
    uniq(&mut b);

    println!("A \\ B:");
    show_diff(&a, &b);

    println!("\nB \\ A:");
    show_diff(&b, &a);

    println!("\nA ^ B:");
    show_sym_diff(&a, &b);
}

