#include <stdio.h>
#include <string.h>

void nb(int cells, int total_block_size, int* blocks, int block_count,
        char* output, int offset, int* count) {
    if (block_count == 0) {
        printf("%2d  %s\n", ++*count, output);
        return;
    }
    int block_size = blocks[0];
    int max_pos = cells - (total_block_size + block_count - 1);
    total_block_size -= block_size;
    cells -= block_size + 1;
    ++blocks;
    --block_count;
    for (int i = 0; i <= max_pos; ++i, --cells) {
        memset(output + offset, '.', max_pos + block_size);
        memset(output + offset + i, '#', block_size);
        nb(cells, total_block_size, blocks, block_count, output,
           offset + block_size + i + 1, count);
    }
}

void nonoblock(int cells, int* blocks, int block_count) {
    printf("%d cells and blocks [", cells);
    for (int i = 0; i < block_count; ++i)
        printf(i == 0 ? "%d" : ", %d", blocks[i]);
    printf("]:\n");
    int total_block_size = 0;
    for (int i = 0; i < block_count; ++i)
        total_block_size += blocks[i];
    if (cells < total_block_size + block_count - 1) {
        printf("no solution\n");
        return;
    }
    char output[cells + 1];
    memset(output, '.', cells);
    output[cells] = '\0';
    int count = 0;
    nb(cells, total_block_size, blocks, block_count, output, 0, &count);
}

int main() {
    int blocks1[] = {2, 1};
    nonoblock(5, blocks1, 2);
    printf("\n");

    nonoblock(5, NULL, 0);
    printf("\n");

    int blocks2[] = {8};
    nonoblock(10, blocks2, 1);
    printf("\n");

    int blocks3[] = {2, 3, 2, 3};
    nonoblock(15, blocks3, 4);
    printf("\n");

    int blocks4[] = {2, 3};
    nonoblock(5, blocks4, 2);

    return 0;
}

ccd6da3930dba01c9e7a89ebcd3ddfcb.rust_code:
use std::fmt::Write;

fn nb(cells: usize, total_block_size: usize, blocks: &[usize], output: &mut String, offset: usize, count: &mut usize) {
    if blocks.is_empty() {
        *count += 1;
        println!("{:2}  {}", count, output);
        return;
    }

    let block_size = blocks[0];
    let max_pos = cells - (total_block_size + blocks.len() - 1);
    let remaining_total_block_size = total_block_size - block_size;
    let remaining_cells = cells - block_size - 1;

    for i in 0..=max_pos {
        let end = offset + max_pos + block_size;
        output.replace_range(offset..end, &".".repeat(max_pos + block_size));
        output.replace_range(offset + i..offset + i + block_size, &"#".repeat(block_size));
        nb(remaining_cells, remaining_total_block_size, &blocks[1..], output, offset + block_size + i + 1, count);
    }
}

fn nonoblock(cells: usize, blocks: Option<&[usize]>, block_count: usize) {
    print!("{} cells and blocks [", cells);
    if let Some(blocks) = blocks {
        for (i, &block) in blocks.iter().enumerate() {
            print!("{}", if i == 0 { "" } else { ", " });
            print!("{}", block);
        }
    }
    println!("]:\n");

    let total_block_size = blocks.map_or(0, |b| b.iter().sum());
    if cells < total_block_size + block_count - 1 {
        println!("no solution");
        return;
    }

    let mut output = ".".repeat(cells);
    let mut count = 0;
    nb(cells, total_block_size, blocks.unwrap_or(&[]), &mut output, 0, &mut count);
}

fn main() {
    let blocks1 = vec![2, 1];
    nonoblock(5, Some(&blocks1), 2);
    println!();

    nonoblock(5, None, 0);
    println!();

    let blocks2 = vec![8];
    nonoblock(10, Some(&blocks2), 1);
    println!();

    let blocks3 = vec![2, 3, 2, 3];
    nonoblock(15, Some(&blocks3), 4);
    println!();

    let blocks4 = vec![2, 3];
    nonoblock(5, Some(&blocks4), 2);
}

