use std::process;

fn f(n: i32, x: i32, y: i32) -> i32 {
    (x + y * 2 + 1) % n
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() != 2 {
        process::exit(1);
    }

    let n: i32 = match args[1].parse() {
        Ok(num) => num,
        Err(_) => process::exit(1),
    };

    if n < 3 || n % 2 == 0 {
        process::exit(2);
    }

    for i in 0..n {
        for j in 0..n {
            print!("{:4}", f(n, n - j - 1, i) * n + f(n, j, i) + 1);
        }
        println!();
    }
    println!("\nMagic Constant: {}.", (n * n + 1) / 2 * n);
}

