        print!("a = {}\r", a);
        io::stdout().flush().unwrap();

        for b in (a + 1)..max_p / 2 {
            let bb = XInt::from(b) * XInt::from(b);
            for c in (b + 1)..max_p / 2 {
                let cc = XInt::from(c) * XInt::from(c);
                if aa + bb < cc {
                    break;
                }
                if a + b + c > max_p {
                    break;
                }

                if aa + bb == cc {
                    pytha += 1;
                    if gcd(a, b) == 1 {
                        prim += 1;
                    }
                }
            }
        }
    }

    println!("Up to {}, there are {} triples, of which {} are primitive", max_p, pytha, prim);
