    name: &'static str,
    days: i32,
    start_wday: i32,
    at: i32,
}

fn space(n: usize) {
    for _ in 0..n {
        print!(" ");
    }
}

fn init_months(year: i32, months: &mut [Month; 12]) -> (usize, usize, usize) {
    let mut year = year;
    if (year % 4 == 0 && year % 100 != 0) || year % 400 == 0 {
        months[1].days = 29;
    }

    year -= 1;
    months[0].start_wday = (year * 365 + year / 4 - year / 100 + year / 400 + 1) % 7;

