    while 12 % cols != 0 {
        cols -= 1;
    }
    let gap = if cols > 1 { (WIDTH - 20 * cols) / (cols - 1) } else { 0 };
    let gap = if gap > 4 { 4 } else { gap };
    let lead = (WIDTH - (20 + gap) * cols + gap + 1) / 2;
    year += 1;

    (cols, lead, gap)
}

