#include <stdio.h>

int main() {    
    int n, b, d;
    unsigned long long i, j, sum, fact[12];

    fact[0] = 1;
    for (n = 1; n < 12; ++n) {
        fact[n] = fact[n-1] * n;
    }

    for (b = 9; b <= 12; ++b) {
        printf("The factorions for base %d are:\n", b);
        for (i = 1; i < 1500000; ++i) {
            sum = 0;
            j = i;
            while (j > 0) {
                d = j % b;
                sum += fact[d];
                j /= b;
            }
            if (sum == i) printf("%llu ", i);
        }
        printf("\n\n");
    }
    return 0;
}

fd2649b2337170f1e2f4acab4f89b642.rust_code:
fn main() {
    let mut fact = vec![0u64; 12];
    fact[0] = 1;
    for n in 1..12 {
        fact[n] = fact[n - 1] * n as u64;
    }

    for &base in &[9, 10, 11, 12] {
        println!("The factorions for base {} are:", base);
        for i in 1..1500000 {
            let mut sum = 0;
            let mut j = i;
            while j > 0 {
                let digit = j % base as u64;
                sum += fact[digit as usize];
                j /= base as u64;
            }
            if sum == i {
                print!("{} ", i);
            }
        }
        println!();
    }
}

