fn mdr(n: u64) -> (u32, u32) {
    fn _mdr(mut n: u64) -> (u32, u32) {
        let mut r = if n > 0 { 1 } else { 0 };
        while n > 0 {
            r *= (n % 10) as u32;
            n /= 10;
        }
        if r >= 10 {
            let (new_r, mp) = _mdr(r as u64);
            (new_r, mp + 1)
        } else {
            (r, 1)
        }
    }
    _mdr(n)
}

fn main() {
    const VALUES: [u64; 4] = [123321, 7739, 893, 899998];
    println!("Number    MDR    MP");
    for &value in &VALUES {
        let (vmdr, vmp) = mdr(value);
        println!("{:6}   {:3}   {:3}", value, vmdr, vmp);
    }

    const TWIDTH: usize = 5;
    let mut table: [[u64; TWIDTH]; 10] = [[0; TWIDTH]; 10];
    let mut tfill: [usize; 10] = [0; 10];
    let mut total = 0;
    let mut i = 0;
    while total < 10 * TWIDTH {
        let (vmdr, _) = mdr(i);
        if tfill[vmdr as usize] < TWIDTH {
            table[vmdr as usize][tfill[vmdr as usize]] = i;
            tfill[vmdr as usize] += 1;
            total += 1;
        }
        i += 1;
    }

    println!("\nMDR: [n0..n4]");
    for (i, row) in table.iter().enumerate() {
        print!("{:3}: [", i);
        for (j, &value) in row.iter().enumerate() {
            print!("{}", value);
            if j != TWIDTH - 1 {
                print!(", ");
            }
        }
        println!("]");
    }
}

