fn main() {
    const N: usize = 2200;
    let mut r = vec![0; N + 1];

    for a in 1..=N {
        for b in a..=N {
            if a % 2 != 0 && b % 2 != 0 {
                continue;
            }
            let aabb = a * a + b * b;
            for c in b..=N {
                let aabbcc = aabb + c * c;
                let d = (aabbcc as f64).sqrt() as usize;
                if aabbcc == d * d && d <= N {
                    r[d] = 1;
                }
            }
        }
    }

    for a in 1..=N {
        if r[a] == 0 {
            print!("{} ", a);
        }
    }
    println!();
}

