use std::io::{self, Write};

#[derive(Copy, Clone)]
struct Rgb {
    r: f64,
    g: f64,
    b: f64,
}

fn sc_up(scale: &mut i64, x: &mut i64, y: &mut i64, cscale: &mut i64) {
    *scale *= 2;
    *x *= 2;
    *y *= 2;
    *cscale *= 3;
}

fn h_rgb(pix: &mut [Rgb], x: i64, y: i64, scale: i64, clen: i64, cscale: i64) {
    let index = (y / scale) as usize * ((scale * 2 + 20) as usize) + (x / scale) as usize;
    let p = &mut pix[index];

    const SAT: f64 = 1.0;
    let h = 6.0 * clen as f64 / cscale as f64;
    let val = 1.0;
    let c = SAT * val;
    let x_val = c * (1.0 - f64::abs(f64::rem_euclid(h, 2.0) - 1.0));

    match h as i32 {
        0 => {
            p.r += c;
            p.g += x_val;
        }
        1 => {
            p.r += x_val;
            p.g += c;
        }
        2 => {
            p.g += c;
            p.b += x_val;
        }
        3 => {
            p.g += x_val;
            p.b += c;
        }
        4 => {
            p.r += x_val;
            p.b += c;
        }
        _ => {
            p.r += c;
            p.b += x_val;
        }
    }
}

fn iter_string(str: &str, d: i32, x: &mut i64, y: &mut i64, dx: i64, dy: i64, scale: i64, clen: &mut i64, cscale: i64, pix: &mut [Rgb]) {
    for ch in str.chars() {
        match ch {
            'X' => {
                if d > 0 {
                    iter_string("XHXVX", d - 1, x, y, dx, dy, scale, clen, cscale, pix);
                } else {
                    *clen += 1;
                    h_rgb(pix, *x, *y, scale, *clen, cscale);
                    *x += dx;
                    *y -= dy;
                }
            }
            'V' => {
                let len = 1 << d;
                for _ in 0..len {
                    *clen += 1;
                    h_rgb(pix, *x, *y, scale, *clen, cscale);
                    *y += dy;
                }
            }
            'H' => {
                let len = 1 << d;
                for _ in 0..len {
                    *clen += 1;
                    h_rgb(pix, *x, *y, scale, *clen, cscale);
                    *x -= dx;
                }
            }
            _ => {}
        }
    }
}

fn sierp(leng: i64, depth: i32) {
    let h = leng + 20;
    let w = leng + 20;
    let mut pix = vec![Rgb { r: 0.0, g: 0.0, b: 0.0 }; (h * w) as usize];

    let mut x = 10;
    let mut y = 10;
    let dx = leng;
    let dy = leng;
    let mut scale = 1;
    let mut clen = 0;
    let mut cscale = 3;

    for _ in 0..depth {
        sc_up(&mut scale, &mut x, &mut y, &mut cscale);
    }

    iter_string("VXH", depth, &mut x, &mut y, dx, dy, scale, &mut clen, cscale, &mut pix);

    let mut fpix = vec![0u8; (w * h * 3) as usize];
    let mut maxv = 0.0;

    for p in &pix {
        for &val in &[p.r, p.g, p.b] {
            if val > maxv {
                maxv = val;
            }
        }
    }

    for (i, p) in pix.iter().enumerate() {
        fpix[i * 3] = (p.r * 255.0 / maxv) as u8;
        fpix[i * 3 + 1] = (p.g * 255.0 / maxv) as u8;
        fpix[i * 3 + 2] = (p.b * 255.0 / maxv) as u8;
    }

    writeln!(io::stdout(), "P6\n{} {}\n255", w, h).unwrap();
    io::stdout().write_all(&fpix).unwrap();
    io::stdout().flush().unwrap();
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let depth = if args.len() > 1 { args[1].parse::<i32>().unwrap_or(10) } else { 10 };
    let size = 1 << depth;

    eprintln!("size: {} depth: {}", size, depth);
    sierp(size, depth + 2);
}

