#include <stdio.h>
#include <string.h>

int repstr(char *str)
{
    if (!str) return 0;

    size_t sl = strlen(str) / 2;
    while (sl > 0) {
        if (strstr(str, str + sl) == str)
            return sl;
        --sl;
    }

    return 0;
}

int main(void)
{
    char *strs[] = { "1001110011", "1110111011", "0010010010", "1111111111",
        "0100101101", "0100100", "101", "11", "00", "1" };

    size_t strslen = sizeof(strs) / sizeof(strs[0]);
    size_t i;
    for (i = 0; i < strslen; ++i) {
        int n = repstr(strs[i]);
        if (n)
            printf("\"%s\" = rep-string \"%.*s\"\n", strs[i], n, strs[i]);
        else
            printf("\"%s\" = not a rep-string\n", strs[i]);
    }

    return 0;
}

9e6b37b0d7c36b42fa86e3610329b781.rust_code:
fn repstr(s: &str) -> usize {
    let sl = s.len() / 2;
    for len in (1..=sl).rev() {
        if s.starts_with(&s[len..]) {
            return len;
        }
    }
    0
}

fn main() {
    let strs = [
        "1001110011", "1110111011", "0010010010", "1111111111",
        "0100101101", "0100100", "101", "11", "00", "1",
    ];

    for s in &strs {
        match repstr(s) {
            0 => println!("\"{}\" = not a rep-string", s),
            n => println!("\"{}\" = rep-string \"{}\"", s, &s[..n]),
        }
    }
}

