#include<stdio.h>
#define de 0
#define pe 1
#define ab 2

int main(){
	int sum = 0, i, j;
	int try_max = 0;

	int   count_list[3] = {1,0,0};
	for(i=2; i <= 20000; i++){

		try_max = i/2;

		sum = 1;
		for(j=2; j<try_max; j++){

			if (i % j)
				continue; 

			try_max = i/j;

			sum += j;
			if (j != try_max)
				sum += try_max;
		}

		if (sum < i){
			count_list[de]++;
			continue;
		}
		if (sum > i){
			count_list[ab]++;
			continue;
		}
		count_list[pe]++;
	}
	printf("\nThere are %d deficient," ,count_list[de]);
	printf(" %d perfect," ,count_list[pe]);
	printf(" %d abundant numbers between 1 and 20000.\n" ,count_list[ab]);
return 0;
}

43081755d141da7ab1efccf264c74c65.rust_code:
fn main() {
    let mut sum = 0;
    let mut try_max = 0;
    let mut count_list = [1, 0, 0];

    for i in 2..=20000 {
        try_max = i / 2;
        sum = 1;

        for j in 2..try_max {
            if i % j != 0 {
                continue;
            }

            try_max = i / j;

            sum += j;
            if j != try_max {
                sum += try_max;
            }
        }

        match sum.cmp(&i) {
            std::cmp::Ordering::Less => count_list[0] += 1,
            std::cmp::Ordering::Greater => count_list[2] += 1,
            std::cmp::Ordering::Equal => count_list[1] += 1,
        }
    }

    println!(
        "There are {} deficient, {} perfect, {} abundant numbers between 1 and 20000.",
        count_list[0], count_list[1], count_list[2]
    );
}

