fn det_in(in_matrix: &[&[f64]], n: usize, perm: bool) -> f64 {
    if n == 1 {
        return in_matrix[0][0];
    }

    let mut sum = 0.0;
    let mut m: Vec<&[f64]> = in_matrix.iter().skip(1).cloned().collect();

    let mut sgn = 1;
    for i in 0..=n {
        sum += sgn as f64 * (in_matrix[i][0] * det_in(&m, n - 1, perm));
        if i == n {
            break;
        }

        m[i] = &in_matrix[i][1..];
        if !perm {
            sgn = -sgn;
        }
    }
    sum
}

fn det(in_array: &[f64], n: usize, perm: bool) -> f64 {
    let m: Vec<&[f64]> = in_array.chunks(n).collect();
    det_in(&m, n, perm)
}

