    match n {
        0 => 0,
        _ => n - f(m(n - 1)),
    }
}

fn main() {
    for i in 0..20 {
        print!("{:2} ", f(i));
    }
    println!();
    for i in 0..20 {
        print!("{:2} ", m(i));
    }
    println!();
}

