fn main() {
    const N: usize = 100000;
    let mut q = vec![0; N + 1];
    q[1] = 1;
    q[2] = 1;

    for i in 3..=N {
        q[i] = q[i - q[i - 1]] + q[i - q[i - 2]];
    }

    for i in 1..=10 {
        print!("{}{}", q[i], if i == 10 { '\n' } else { ' ' });
    }

    println!("{}", q[1000]);

    let flip = q.windows(2).filter(|w| w[0] > w[1]).count();
    println!("flips: {}", flip);
}

