	if (c < 2 || (n = atoi(v[1])) <= 0 || n > 25) n = 5;


	append(0);

	mktrees((uint)n);
	fprintf(stderr, "Number of %d-trees: %u\n", n, offset[n+1] - offset[n]);
	listtrees((uint)n);

	return 0;
}

