fn isqrt(x: i64) -> i64 {
    let mut q = 1;
    let mut r = 0;
    while q <= x {
        q <<= 2;
    }
    while q > 1 {
        q >>= 2;
        let t = x - r - q;
        r >>= 1;
        if t >= 0 {
            r += q;
        }
    }
    r
}

fn main() {
    println!("Integer square root for numbers 0 to 65:");
    for n in 0..=65 {
        print!("{} ", isqrt(n));
    }
    println!();

    println!("\nInteger square roots of odd powers of 7 from 1 to 21:");
    println!(" n |              7 ^ n | isqrt(7 ^ n)");
    let mut p = 7;
    for n in (1..=21).step_by(2) {
        println!("{:2} | {:18} | {:12}", n, p, isqrt(p));
        p *= 49;
    }
}

