#include <stdlib.h>
#include <string.h>
#include <stdio.h>

double* fwd_diff(double* x, unsigned int len, unsigned int order)
{
	unsigned int i, j;
	double* y;


	if (order >= len) return 0;

	y = malloc(sizeof(double) * len);
	if (!order) {
		memcpy(y, x, sizeof(double) * len);
		return y;
	}


	for (j = 0; j < order; j++, x = y)
		for (i = 0, len--; i < len; i++)
			y[i] = x[i + 1] - x[i];

	y = realloc(y, sizeof(double) * len);
	return y;
}

int main(void)
{
	double *y, x[] = {90, 47, 58, 29, 22, 32, 55, 5, 55, 73};
	int i, len = sizeof(x) / sizeof(x[0]);

	y = fwd_diff(x, len, 1);
	for (i = 0; i < len - 1; i++)
		printf("%g ", y[i]);
	putchar('\n');

	return 0;
}

c9f9504c7f26d9f556e737d042937fbe.rust_code:
fn fwd_diff(x: &[f64], order: usize) -> Option<Vec<f64>> {
    if order >= x.len() {
        return None;
    }

    let mut y = x.to_vec();

    if order == 0 {
        return Some(y);
    }

    for _ in 0..order {
        y = y.windows(2).map(|w| w[1] - w[0]).collect();
    }

    Some(y)
}

fn main() {
    let x = [90.0, 47.0, 58.0, 29.0, 22.0, 32.0, 55.0, 5.0, 55.0, 73.0];
    if let Some(y) = fwd_diff(&x, 1) {
        for &val in &y {
            print!("{} ", val);
        }
        println!();
    }
}

