#include <stdio.h>
#include <stdlib.h>

int main(int c, char **v)
{
	int i, j, m, n, *s;


	if (c < 2 || ((m = atoi(v[1]))) <= 0) m = 5;


	s = malloc(sizeof(int) * m * m);

	for (i = n = 0; i < m * 2; i++)
		for (j = (i < m) ? 0 : i-m+1; j <= i && j < m; j++)
			s[(i&1)? j*(m-1)+i : (i-j)*m+j ] = n++;

	for (i = 0; i < m * m; putchar((++i % m) ? ' ':'\n'))
		printf("%3d", s[i]);


	return 0;
}

92f662d3bb207920e0a00ec200f9473c.rust_code:
use std::env;

fn main() {
    let args: Vec<String> = env::args().collect();
    let m = match args.get(1).and_then(|s| s.parse::<usize>().ok()) {
        Some(m) if m > 0 => m,
        _ => 5,
    };

    let mut s = vec![0; m * m];

    for i in 0..(m * 2) {
        for j in if i < m { 0 } else { i - m + 1 }..=i.min(m - 1) {
            let index = if i & 1 == 1 {
                j * (m - 1) + i
            } else {
                (i - j) * m + j
            };
            s[index] = i * m + j - if i >= m { (i - m + 1) * m } else { 0 };
        }
    }

    for (i, &value) in s.iter().enumerate() {
        print!("{:3}", value);
        if (i + 1) % m == 0 {
            println!();
        } else {
            print!(" ");
        }
    }
}

