fn self_desc(mut xx: u64) -> bool {
    let mut cnt = [0; 10];
    let mut dig = [0; 10];
    let mut d = 0;

    while xx > u32::MAX as u64 {
        let digit = (xx % 10) as usize;
        dig[d] = digit;
        cnt[digit] += 1;
        xx /= 10;
        d += 1;
    }

    while xx > 0 {
        let digit = (xx % 10) as usize;
        dig[d] = digit;
        cnt[digit] += 1;
        xx /= 10;
        d += 1;
    }

    for i in 0..d {
        if dig[i] != cnt[i] {
            return false;
        }
    }

    true
}

fn main() {
    for i in 1..100000000 {
        if self_desc(i) {
            println!("{}", i);
        }
    }
}

