#include <stdio.h>
#include <stdlib.h>


int F(const int n);
int M(const int n);

int F(const int n)
{
  return (n == 0) ? 1 : n - M(F(n - 1));
}

int M(const int n)
{
  return (n == 0) ? 0 : n - F(M(n - 1));
}

int main(void)
{
  int i;
  for (i = 0; i < 20; i++)
    printf("%2d ", F(i));
  printf("\n");
  for (i = 0; i < 20; i++)
    printf("%2d ", M(i));
  printf("\n");
  return EXIT_SUCCESS;
}

7d5ccd4d26b4d4119713dad46ca65ec6.rust_code:
fn f(n: i32) -> i32 {
    match n {
        0 => 1,
        _ => n - m(f(n - 1)),
    }
}

fn m(n: i32) -> i32 {
    match n {
        0 => 0,
        _ => n - f(m(n - 1)),
    }
}

fn main() {
    for i in 0..20 {
        print!("{:2} ", f(i));
    }
    println!();
    for i in 0..20 {
        print!("{:2} ", m(i));
    }
    println!();
}

