    let tens: [XInt; 20] = {
        let mut tens = [0; 20];
        tens[0] = 1;
        for i in 1..20 {
            tens[i] = tens[i - 1] * 10;
        }
        tens
    };

    let lo = max(tens[nd - 1], (x + tens[nd] - 2) / (tens[nd] - 1));
    let hi = min(x / lo, (x as f64).sqrt() as XInt);

    let t = dtally(x);
    for a in lo..=hi {
        let b = x / a;
        if a * b == x && (a % 10 != 0 || b % 10 != 0) && t == dtally(a) + dtally(b) {
            f[n] = a;
            n += 1;
        }
    }

    n
}

fn show_fangs(x: XInt, f: &[XInt], cnt: usize) {
    print!("{}", x);
    for &a in &f[..cnt] {
        let b = x / a;
        print!(" = {} x {}", a, b);
    }
    println!();
}

fn main() {
    let mut f = [0; 16];
    let bigs = [16758243290880, 24959017348650, 14593825548650, 0];

    let mut n = 0;
    for x in 1.. {
        let j = fangs(x, &mut f);
        if j == 0 {
            continue;
        }
        n += 1;
        print!("{:2}: ", n);
        show_fangs(x, &f, j);
        if n >= 25 {
            break;
        }
    }

    println!();
    for &x in &bigs[..bigs.len() - 1] {
        let j = fangs(x, &mut f);
        if j > 0 {
            show_fangs(x, &f, j);
        } else {
            println!("{} is not vampiric", x);
        }
    }
}

