use std::str;

fn rtrim(s: &str) -> &str {
    s.trim_start_matches(|c: char| c.is_whitespace() || !c.is_ascii_graphic())
}

fn ltrim(s: &str) -> &str {
    s.trim_end_matches(|c: char| c.is_whitespace() || !c.is_ascii_graphic())
}

fn trim(s: &str) -> &str {
    let trimmed_left = rtrim(s);
    ltrim(trimmed_left)
}

fn main() {
    let a = "     this is a string      ";
    let b = rtrim(a);
    let c = ltrim(a);
    let d = trim(a);

    println!("'{}'\n'{}'\n'{}'", b, c, d);
}

