use std::env;

fn main() {
    let args: Vec<String> = env::args().collect();
    let top: u32 = args[1].parse().expect("Please provide a valid number");

    let mut divsum = vec![1; (top + 1) as usize];
    let mut pows = [1; 32];
    pows[1] = 0;

    for p in 2..=((top / 2) as u32) {
        if divsum[p as usize] > 1 {
            divsum[p as usize] -= p;
            continue;
        }

        let mut x = 1;
        while pows[x - 1] <= top / p {
            pows[x] = p * pows[x - 1];
            x += 1;
        }

        let mut k = p - 1;
        for n in (p * 2..=top).step_by(p as usize) {
            let mut s = 1 + pows[1];
            k -= 1;

            if k == 0 {
                let mut i = 2;
                while i < x && n % pows[i] == 0 {
                    s += pows[i];
                    i += 1;
                }
                k = p;
            }
            divsum[n as usize] *= s;
        }
    }

    for p in ((top / 2) + 1)..=top {
        if divsum[p as usize] > 1 {
            divsum[p as usize] -= p;
        }
    }

