fn digit_sum(mut n: u32) -> u32 {
    let mut sum = 0;
    while n > 0 {
        sum += n % 10;
        n /= 10;
    }
    sum
}

fn a131382(n: u32) -> u32 {
    let mut m = 1;
    loop {
        if n == digit_sum(m * n) {
            break m;
        }
        m += 1;
    }
}

fn main() {
    for n in 1..=70 {
        print!("{:>9}", a131382(n));
        if n % 10 == 0 {
            println!();
        }
    }
}

