#include <stdio.h>
#include <string.h>

void print_verse(const char *name) {
    char *x, *y; 
    int b = 1, f = 1, m = 1, i = 1;


    x = strdup(name);     
    x[0] = toupper(x[0]);
    for (; x[i]; ++i) x[i] = tolower(x[i]);

    if (strchr("AEIOU", x[0])) {
        y = strdup(x);
        y[0] = tolower(y[0]); 
    }
    else {
        y = x + 1;
    }

    switch(x[0]) {
        case 'B': b = 0; break;
        case 'F': f = 0; break;
        case 'M': m = 0; break;
        default : break;
    }

    printf("%s, %s, bo-%s%s\n", x, x, (b) ? "b" : "", y);
    printf("Banana-fana fo-%s%s\n", (f) ? "f" : "", y);
    printf("Fee-fi-mo-%s%s\n", (m) ? "m" : "", y);
    printf("%s!\n\n", x);
}

int main() {
    int i;
    const char *names[6] = {"gARY", "Earl", "Billy", "Felix", "Mary", "sHIRley"};
    for (i = 0; i < 6; ++i) print_verse(names[i]);
    return 0;
}

9ac2b12703b7ef606b1adad657399e3f.rust_code:
use std::ascii::AsciiExt;

fn print_verse(name: &str) {
    let mut x = name.to_string();
    x.replace_range(0..1, &x[0..1].to_ascii_uppercase());
    x.replace_range(1.., &x[1..].to_ascii_lowercase());

    let y = match x.chars().next().unwrap() {
        'A' | 'E' | 'I' | 'O' | 'U' => x[1..].to_ascii_lowercase(),
        _ => x[1..].to_string(),
    };

    let b = !matches!(x.chars().next().unwrap(), 'B');
    let f = !matches!(x.chars().next().unwrap(), 'F');
    let m = !matches!(x.chars().next().unwrap(), 'M');

    println!("{}, {}, bo-{}{}", x, x, if b { "b" } else { "" }, y);
    println!("Banana-fana fo-{}{}", if f { "f" } else { "" }, y);
    println!("Fee-fi-mo-{}{}", if m { "m" } else { "" }, y);
    println!("{}!\n", x);
}

fn main() {
    let names = ["gARY", "Earl", "Billy", "Felix", "Mary", "sHIRley"];
    for name in &names {
        print_verse(name);
    }
}

