use std::env;
use std::f64::consts::PI;

fn day(y: i32, m: i32, d: i32) -> i32 {
    367 * y - 7 * (y + (m + 9) / 12) / 4 + 275 * m / 9 + d - 730530
}

fn cycle(diff: i32, l: i32, t: &str) {
    let p = (100.0 * (2.0 * PI * diff as f64 / l as f64).sin()).round() as i32;
    print!("{:>12} cycle: {:>3}%", t, p);
    if p.abs() < 15 {
        print!(" (critical day)");
    }
    println!();
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 7 {
        println!("Usage:\ncbio y1 m1 d1 y2 m2 d2");
        std::process::exit(1);
    }

    let diff = (day(args[1].parse().unwrap(), args[2].parse().unwrap(), args[3].parse().unwrap())
        - day(args[4].parse().unwrap(), args[5].parse().unwrap(), args[6].parse().unwrap())).abs();
    println!("Age: {} days", diff);
    cycle(diff, 23, "Physical");
    cycle(diff, 28, "Emotional");
    cycle(diff, 33, "Intellectual");
}

