#include <stdio.h>

inline int self_desc(unsigned long long xx)
{
	register unsigned int d, x;
	unsigned char cnt[10] = {0}, dig[10] = {0};

	for (d = 0; xx > ~0U; xx /= 10)
		cnt[ dig[d++] = xx % 10 ]++;

	for (x = xx; x; x /= 10)
		cnt[ dig[d++] = x % 10 ]++;

	while(d-- && dig[x++] == cnt[d]);

	return d == -1;
}

int main()
{
	int i;
	for (i = 1; i < 100000000; i++) 
		if (self_desc(i)) printf("%d\n", i);

	return 0;
}

c36bd28b5fed79e0223bd1c2598fc674.rust_code:
fn self_desc(mut xx: u64) -> bool {
    let mut cnt = [0; 10];
    let mut dig = [0; 10];
    let mut d = 0;

    while xx > u32::MAX as u64 {
        let digit = (xx % 10) as usize;
        dig[d] = digit;
        cnt[digit] += 1;
        xx /= 10;
        d += 1;
    }

    while xx > 0 {
        let digit = (xx % 10) as usize;
        dig[d] = digit;
        cnt[digit] += 1;
        xx /= 10;
        d += 1;
    }

    for i in 0..d {
        if dig[i] != cnt[i] {
            return false;
        }
    }

    true
}

fn main() {
    for i in 1..100000000 {
        if self_desc(i) {
            println!("{}", i);
        }
    }
}

