use std::fmt::Write;

fn factorial(n: u64) -> u64 {
    let mut res = 1;
    if n == 0 {
        return res;
    }
    let mut n = n;
    while n > 0 {
        res *= n;
        n -= 1;
    }
    res
}

fn lah(n: u64, k: u64) -> u64 {
    match (k, n) {
        (1, _) => factorial(n),
        (_, n) if k == n => 1,
        (_, n) if k > n => 0,
        (k, _) if k < 1 || n < 1 => 0,
        _ => (factorial(n) * factorial(n - 1)) / (factorial(k) * factorial(k - 1)) / factorial(n - k),
    }
}

fn main() {
    println!("Unsigned Lah numbers: L(n, k):");
    print!("n/k ");
    for i in 0..13 {
        print!("{:>10} ", i);
    }
    println!();
    for row in 0..13 {
        print!("{:<3}", row);
        for i in 0..=row {
