fn lpd(n: u32) -> u32 {
    if n <= 1 {
        return 1;
    }
    for i in (1..n).rev() {
        if n % i == 0 {
            return i;
        }
    }
    1 // Fallback, though logically unreachable
}

fn main() {
    for i in 1..=100 {
        print!("{:3}", lpd(i));
        if i % 10 == 0 {
            println!();
        }
    }
}

