#include <stdio.h>

unsigned int lpd(unsigned int n) {
    if (n<=1) return 1;
    int i;
    for (i=n-1; i>0; i--)
        if (n%i == 0) return i;   
}

int main() {
    int i;
    for (i=1; i<=100; i++) {
        printf("%3d", lpd(i));
        if (i % 10 == 0) printf("\n");
    }
    return 0;
}

87013c41390beafcdd4e6257bd6b13ae.rust_code:
fn lpd(n: u32) -> u32 {
    if n <= 1 {
        return 1;
    }
    for i in (1..n).rev() {
        if n % i == 0 {
            return i;
        }
    }
    1 // Fallback, though logically unreachable
}

fn main() {
    for i in 1..=100 {
        print!("{:3}", lpd(i));
        if i % 10 == 0 {
            println!();
        }
    }
}

