use std::cmp::Ordering;
use std::io::{self, Write};
use std::str::FromStr;

fn main() {
    const MAX: usize = 3;
    let mut values = vec![String::with_capacity(100); MAX];
    let mut vals = vec![0.0; MAX];
    let mut is_string = false;

    for (i, value) in values.iter_mut().enumerate() {
        print!("Enter {}{} value: ", i + 1, match i {
            0 => "st",
            1 => "nd",
            2 => "rd",
            _ => unreachable!(),
        });
        io::stdout().flush().unwrap();
        io::stdin().read_line(value).expect("Failed to read line");

        if !value.trim().chars().all(|c| c.is_digit(10) || c == '.' || c == '-' || c == '+') {
            is_string = true;
        }
    }

    if !is_string {
        for (value, val) in values.iter().zip(vals.iter_mut()) {
            *val = f64::from_str(value.trim()).unwrap_or(0.0);
        }
    }

    for i in 0..MAX - 1 {
        for j in i + 1..MAX {
            if !is_string && vals[i] > vals[j] {
                vals.swap(i, j);
            } else if values[i].chars().next() > values[j].chars().next() {
                values.swap(i, j);
            }
        }
    }

    for (i, value) in values.iter().enumerate() {
        if is_string {
            println!("{} = {}", (b'X' + i as u8) as char, value.trim());
        } else {
            println!("{} = {:.1}", (b'X' + i as u8) as char, vals[i]);
        }
    }
}

