use std::io::{self, Write};

fn main() -> io::Result<()> {
    let mut bounds = [1, 100];
    let mut input = String::new();

    println!("Choose a number between {} and {}.", bounds[0], bounds[1]);

    loop {
        let choice = (bounds[0] + bounds[1]) / 2;

        print!("Is the number {}? (Y/H/L) ", choice);
        io::stdout().flush()?;

        input.clear();
        io::stdin().read_line(&mut input)?;

        match input.trim().chars().next() {
            Some('H') => bounds[1] = choice,
            Some('L') => bounds[0] = choice,
            Some('Y') => {
                println!("\nAwwwright");
                break;
            }
            _ => {}
        }
    }

    Ok(())
}

