use std::io::{self, Write};

fn leonardo(a: i32, b: i32, step: i32, num: usize) {
    print!("First 25 Leonardo numbers: ");
    let mut a = a;
    let mut b = b;

    for i in 1..=num {
        match i {
            1 => print!(" {}", a),
            2 => print!(" {}", b),
            _ => {
                let next = a + b + step;
                print!(" {}", next);
                a = b;
                b = next;
            }
        }
    }
    println!();
}

