use std::cmp::Ordering;

#[derive(Debug)]
struct BString {
    len: usize,
    alloc: usize,
    s: Vec<u8>,
}

impl BString {
    fn new(len: usize) -> Self {
        let mut alloc = len;
        if alloc < 8 {
            alloc = 8;
        }
        BString {
            len: 0,
            alloc,
            s: vec![0; alloc],
        }
    }

    fn extend(&mut self) {
        let mut ns = self.alloc * 2;
        if ns - self.alloc > 1024 {
            ns = self.alloc + 1024;
        }
        self.s.resize(ns, 0);
        self.alloc = ns;
    }

    fn cmp(&self, other: &Self) -> Ordering {
        let len = self.len.min(other.len);
        match self.s[..len].cmp(&other.s[..len]) {
            Ordering::Equal => self.len.cmp(&other.len),
            other => other,
        }
    }

    fn dup(&self) -> Self {
        let mut x = BString::new(self.len);
        x.s[..self.len].copy_from_slice(&self.s[..self.len]);
        x.len = self.len;
        x
    }

    fn from_chars(t: Option<&str>) -> Self {
        match t {
            Some(t) => {
                let l = t.len();
                let mut x = BString::new(l + 1);
                x.s[..l].copy_from_slice(t.as_bytes());
                x.len = l;
                x
            }
            None => BString::new(0),
        }
    }

    fn append(&mut self, b: u8) {
        if self.len >= self.alloc {
            self.extend();
        }
        self.s[self.len] = b;
        self.len += 1;
    }

    fn substr(&self, from: isize, to: isize) -> Option<Self> {
        let from = if from < 0 { (self.len as isize + from) as usize } else { from as usize };
        let to = if to == 0 { self.len } else { to as usize };

        if from >= self.len || from >= to {
            return None;
        }

        let len = to - from;
        let mut x = BString::new(len);
        x.s[..len].copy_from_slice(&self.s[from..to]);
        x.len = len;
        Some(x)
    }

    fn cat(&mut self, s2: &Self) {
        while self.alloc < self.len + s2.len {
            self.extend();
        }
        self.s[self.len..self.len + s2.len].copy_from_slice(&s2.s[..s2.len]);
        self.len += s2.len;
    }

    fn swap(&mut self, other: &mut Self) {
        std::mem::swap(&mut self.alloc, &mut other.alloc);
        std::mem::swap(&mut self.len, &mut other.len);
        std::mem::swap(&mut self.s, &mut other.s);
    }

    fn subst(&mut self, pat: &Self, repl: &Self) {
        let mut tmp = BString::new(0);
        let mut i = 0;
        while i + pat.len <= self.len {
            if &self.s[i..i + pat.len] != &pat.s[..] {
                tmp.append(self.s[i]);
                i += 1;
            } else {
                tmp.cat(repl);
                i += pat.len;
                if pat.len == 0 {
                    tmp.append(self.s[i]);
                    i += 1;
                }
            }
        }
        while i < self.len {
            tmp.append(self.s[i]);
            i += 1;
        }
        self.swap(&mut tmp);
    }

    fn set(&mut self, src: &Self) {
        while self.len < src.len {
            self.extend();
        }
        self.s[..src.len].copy_from_slice(&src.s[..src.len]);
        self.len = src.len;
    }
}

fn main() {
    let mut s = BString::from_chars(Some("aaaaHaaaaaFaaaaHa"));
    let s2 = BString::from_chars(Some("___."));
    let s3 = BString::from_chars(None);

    s.subst(&s3, &s2);
    println!("{}", String::from_utf8_lossy(&s.s[..s.len]));

    // Memory is automatically managed by Rust, no need to manually delete
}

