fn strsort(s: &mut [u8]) {
    let mut n = [0; 256];
    for &byte in s.iter() {
        n[byte as usize] += 1;
    }
    let mut t = s.iter_mut();
    for (i, &count) in n.iter().enumerate() {
        for _ in 0..count {
            if let Some(byte) = t.next() {
                *byte = i as u8;
            }
        }
    }
}

