use std::f64::consts::PI;

fn main() {
    let pi2 = 2.0 * PI;
    for n in 1..10 {
        for (i, _) in (0..n).enumerate() {
            let (mut c, mut s) = (0.0, 0.0);
            match i {
                0 => c = 1.0,
                _ if n == 4 * i => s = 1.0,
                _ if n == 2 * i => c = -1.0,
                _ if 3 * n == 4 * i => s = -1.0,
                _ => {
                    let a = i as f64 * pi2 / n as f64;
                    c = a.cos();
                    s = a.sin();
                }
            }

            if c != 0.0 {
                print!("{:.2}", c);
            }
            match s {
                1.0 => print!("i"),
                -1.0 => print!("-i"),
                _ if s != 0.0 => print!("{:+.2}i", s),
                _ => {}
            }
            if i == n - 1 {
                println!();
            } else {
                print!(",  ");
            }
        }
    }
}

