#include <stdio.h>

unsigned digit_sum(unsigned n) {
    unsigned sum = 0;
    do { sum += n % 10; }
    while(n /= 10);
    return sum;
}

unsigned a131382(unsigned n) {
    unsigned m;
    for (m = 1; n != digit_sum(m*n); m++);
    return m;
}

int main() {
    unsigned n;
    for (n = 1; n <= 70; n++) {
        printf("%9u", a131382(n));
        if (n % 10 == 0) printf("\n");
    }
    return 0;
}

1bc2a9ca7b5daedb4c6e479afbd49c0b.rust_code:
fn digit_sum(mut n: u32) -> u32 {
    let mut sum = 0;
    while n > 0 {
        sum += n % 10;
        n /= 10;
    }
    sum
}

fn a131382(n: u32) -> u32 {
    let mut m = 1;
    loop {
        if n == digit_sum(m * n) {
            break m;
        }
        m += 1;
    }
}

fn main() {
    for n in 1..=70 {
        print!("{:9}", a131382(n));
        if n % 10 == 0 {
            println!();
        }
    }
}

