use std::cmp;

fn fusc(n: u32) -> u32 {
    match n {
        0 | 1 => n,
        _ if n % 2 == 0 => fusc(n / 2),
        _ => fusc((n - 1) / 2) + fusc((n + 1) / 2),
    }
}

fn num_len(mut n: u32) -> usize {
    let mut sum = 1;
    while n > 9 {
        n /= 10;
        sum += 1;
    }
    sum
}

fn print_large_fuscs(limit: u32) {
    println!("\n\nPrinting all largest Fusc numbers up to {}\nIndex-------Value", limit);
    let mut max_len = 1;

    for i in 0..=limit {
        let f = fusc(i);
        let len = num_len(f);

        if len > max_len {
            max_len = len;
            println!("{:5} {:12}", i, f);
        }
    }
}

fn main() {
    println!("Index-------Value");
    for i in 0..61 {
        println!("{:5} {:12}", i, fusc(i));
    }
    print_large_fuscs(u32::MAX);
}

