use std::env;
use std::process;

const WIDTH: usize = 80;
const YEAR_DEFAULT: i32 = 1969;
const WDAYS: [&str; 7] = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];

struct Month {
    name: &'static str,
    days: i32,
    start_wday: i32,
    at: i32,
}

fn space(n: usize) {
    for _ in 0..n {
        print!(" ");
    }
}

fn init_months(year: i32, months: &mut [Month; 12]) -> (usize, usize, usize) {
    let mut year = year;
    if (year % 4 == 0 && year % 100 != 0) || year % 400 == 0 {
        months[1].days = 29;
    }

    year -= 1;
    months[0].start_wday = (year * 365 + year / 4 - year / 100 + year / 400 + 1) % 7;

    for i in 1..12 {
        months[i].start_wday = (months[i - 1].start_wday + months[i - 1].days) % 7;
    }

    let mut cols = (WIDTH + 2) / 22;
    while 12 % cols != 0 {
        cols -= 1;
    }
