#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>

typedef uint64_t xint;
typedef unsigned long long ull;

xint tens[20];

inline xint max(xint a, xint b) { return a > b ? a : b; }
inline xint min(xint a, xint b) { return a < b ? a : b; }
inline int ndigits(xint x)
{
	int n = 0;
	while (x) n++, x /= 10;
	return n;
}

inline xint dtally(xint x)
{
	xint t = 0;
	while (x) t += 1<<((x%10) * 6), x /= 10;

	return t;
}

int fangs(xint x, xint *f)
{
	int n = 0;
	int nd = ndigits(x);
	if (nd & 1) return 0;
	nd /= 2;

	xint lo, hi;
	lo = max(tens[nd-1], (x + tens[nd] - 2)/ (tens[nd] - 1));
	hi = min(x / lo, sqrt(x));

	xint a, b, t = dtally(x);
	for (a = lo; a <= hi; a++) {
		b = x / a;
		if (a * b == x && ((a%10) || (b%10)) && t == dtally(a) + dtally(b))
			f[n++] = a;
	}

	return n;
}

void show_fangs(xint x, xint *f, xint cnt)
{
	printf("%llu", (ull)x);
	int i;
	for (i = 0; i < cnt; i++)
		printf(" = %llu x %llu", (ull)f[i], (ull)(x / f[i]));
	putchar('\n');
}

int main(void)
{
	int i, j, n;
	xint x, f[16], bigs[] = {16758243290880ULL, 24959017348650ULL, 14593825548650ULL, 0};

	tens[0] = 1;
	for (i = 1; i < 20; i++)
		tens[i] = tens[i-1] * 10;

	for (x = 1, n = 0; n < 25; x++) {
		if (!(j = fangs(x, f))) continue;
		printf("%2d: ", ++n);
		show_fangs(x, f, j);
	}

	putchar('\n');
	for (i = 0; bigs[i]; i++) {
		if ((j = fangs(bigs[i], f)))
			show_fangs(bigs[i], f, j);
		else
			printf("%llu is not vampiric\n", (ull)bigs[i]);
	}

	return 0;
}

cd4f5a42c3ea53e24c713970a731e675.rust_code:
use std::cmp::{max, min};
use std::f64;

type XInt = u64;

fn ndigits(mut x: XInt) -> usize {
    let mut n = 0;
    while x > 0 {
        n += 1;
        x /= 10;
    }
    n
}

fn dtally(mut x: XInt) -> XInt {
    let mut t = 0;
    while x > 0 {
        t += 1 << ((x % 10) * 6);
        x /= 10;
    }
    t
}

fn fangs(x: XInt, f: &mut [XInt]) -> usize {
    let mut n = 0;
    let nd = ndigits(x);
    if nd % 2 != 0 {
        return 0;
    }
    let nd = nd / 2;

    let tens: [XInt; 20] = {
        let mut tens = [0; 20];
        tens[0] = 1;
        for i in 1..20 {
            tens[i] = tens[i - 1] * 10;
        }
        tens
    };

    let lo = max(tens[nd - 1], (x + tens[nd] - 2) / (tens[nd] - 1));
    let hi = min(x / lo, (x as f64).sqrt() as XInt);

    let t = dtally(x);
    for a in lo..=hi {
        let b = x / a;
        if a * b == x && (a % 10 != 0 || b % 10 != 0) && t == dtally(a) + dtally(b) {
            f[n] = a;
            n += 1;
        }
    }

    n
}

fn show_fangs(x: XInt, f: &[XInt], cnt: usize) {
    print!("{}", x);
    for &a in &f[..cnt] {
        let b = x / a;
        print!(" = {} x {}", a, b);
    }
    println!();
}

fn main() {
    let mut f = [0; 16];
    let bigs = [16758243290880, 24959017348650, 14593825548650, 0];

    let mut n = 0;
    for x in 1.. {
        let j = fangs(x, &mut f);
        if j == 0 {
            continue;
        }
        n += 1;
        print!("{:2}: ", n);
        show_fangs(x, &f, j);
        if n >= 25 {
            break;
        }
    }

    println!();
    for &x in &bigs[..bigs.len() - 1] {
        let j = fangs(x, &mut f);
        if j > 0 {
            show_fangs(x, &f, j);
        } else {
            println!("{} is not vampiric", x);
        }
    }
}

