    let mut p = 2;
    let mut f = 0;
    while f < k && p * p <= n {
        while n % p == 0 {
            f += 1;
            if f >= k {
                break;
            }
            p *= n / p;
        }
        p += 1;
    }
    f + (if n > 1 { 1 } else { 0 }) == k
}

