#include <stdio.h>

int main(){
  int bounds[ 2 ] = {1, 100};
  char input[ 2 ] = "  ";

  int choice = (bounds[ 0 ] + bounds[ 1 ]) / 2;


  printf( "Choose a number between %d and %d.\n", bounds[ 0 ], bounds[ 1 ] );

  do{
    switch( input[ 0 ] ){
      case 'H':
        bounds[ 1 ] = choice;
        break;
      case 'L':
        bounds[ 0 ] = choice;
        break;
      case 'Y':
        printf( "\nAwwwright\n" );
        return 0;
    }
    choice = (bounds[ 0 ] + bounds[ 1 ]) / 2;

    printf( "Is the number %d? (Y/H/L) ", choice );
  }while( scanf( "%1s", input ) == 1 );

  return 0;
}

0088af28e2ca899a7a2f95f9142227e4.rust_code:
use std::io::{self, Write};

fn main() -> io::Result<()> {
    let mut bounds = [1, 100];
    let mut input = String::new();

    println!("Choose a number between {} and {}.", bounds[0], bounds[1]);

    loop {
        let choice = (bounds[0] + bounds[1]) / 2;

        print!("Is the number {}? (Y/H/L) ", choice);
        io::stdout().flush()?;

        input.clear();
        io::stdin().read_line(&mut input)?;

        match input.trim().chars().next() {
            Some('H') => bounds[1] = choice,
            Some('L') => bounds[0] = choice,
            Some('Y') => {
                println!("\nAwwwright");
                break;
            }
            _ => {}
        }
    }

    Ok(())
}

