    }
    for i in 1..=9 {
        total /= i as f64;
    }

    let gt = pick(&data, 19, 9, 0, treat);
    let le = total as i32 - gt;

    println!("<= : {:.2}%  {}\n > : {:.2}%  {}", 100.0 * le as f64 / total, le, 100.0 * gt as f64 / total, gt);
}

