fn pick(data: &[i32], at: usize, remain: usize, accu: i32, treat: i32) -> i32 {
    if remain == 0 {
        return if accu > treat { 1 } else { 0 };
    }

    let mut result = pick(data, at - 1, remain - 1, accu + data[at - 1], treat);
    if at > remain {
        result += pick(data, at - 1, remain, accu, treat);
    }
    result
}

fn main() {
    let data = [
        85, 88, 75, 66, 25, 29, 83, 39, 97, 68, 41, 10, 49, 16, 65, 32, 92, 28, 98,
    ];
    let mut treat = 0;
    for &value in &data[..9] {
        treat += value;
    }

    let mut total = 1.0;
    for i in 11..=19 {
        total *= i as f64;
    }
    for i in 1..=9 {
        total /= i as f64;
    }

    let gt = pick(&data, 19, 9, 0, treat);
    let le = total as i32 - gt;

    println!("<= : {:.2}%  {}\n > : {:.2}%  {}", 100.0 * le as f64 / total, le, 100.0 * gt as f64 / total, gt);
}

