#include <stdio.h>

void vc(int n, int base, int *num, int *denom)
{
        int p = 0, q = 1;

        while (n) {
                p = p * base + (n % base);
                q *= base;
                n /= base;
        }

        *num = p;  
        *denom = q;

        while (p) { n = p; p = q % p; q = n; }
        *num /= q;
        *denom /= q;
}

int main()
{
        int d, n, i, b;
        for (b = 2; b < 6; b++) {
                printf("base %d:", b);
                for (i = 0; i < 10; i++) {
                        vc(i, b, &n, &d);
                        if (n) printf("  %d/%d", n, d);
                        else   printf("  0");
                }
                printf("\n");
        }

        return 0;
}

17d509f0b68dbce329d9442d80217f43.rust_code:
fn vc(n: i32, base: i32) -> (i32, i32) {
    let mut p = 0;
    let mut q = 1;
    let mut num = n;

    while num != 0 {
        p = p * base + (num % base);
        q *= base;
        num /= base;
    }

    let mut gcd = |mut a: i32, mut b: i32| -> i32 {
        while b != 0 {
            let temp = b;
            b = a % b;
            a = temp;
        }
        a
    };

    let divisor = gcd(p, q);
    (p / divisor, q / divisor)
}

fn main() {
    for base in 2..6 {
        print!("base {}: ", base);
        for i in 0..10 {
            let (num, denom) = vc(i, base);
            if num != 0 {
                print!("  {}/{}", num, denom);
            } else {
                print!("  0");
            }
        }
        println!();
    }
}

