use std::io;

fn player_turn(num_tokens: i32, take: i32) -> i32 {
    if take < 1 || take > 3 {
        println!("\nTake must be between 1 and 3.\n");
        return num_tokens;
    }
    let remaining_tokens = num_tokens - take;
    println!("\nPlayer takes {} tokens.", take);
    println!("{} tokens remaining.\n", remaining_tokens);
    remaining_tokens
}

