fn max(a: &[i32], n: usize, i: usize, j: usize, k: usize) -> usize {
    let mut m = i;
    if j < n && a[j] > a[m] {
        m = j;
    }
    if k < n && a[k] > a[m] {
        m = k;
    }
    m
}

fn downheap(a: &mut [i32], n: usize, mut i: usize) {
    while let Some(j) = (2 * i + 1..).take(2).filter(|&x| x < n).map(|x| max(a, n, i, x, x + 1)).next() {
        if j == i {
            break;
        }
        a.swap(i, j);
        i = j;
    }
}

fn heapsort(a: &mut [i32]) {
    let n = a.len();
    for i in (0..=(n - 2) / 2).rev() {
        downheap(a, n, i);
    }
    for i in 0..n {
        a.swap(n - i - 1, 0);
        downheap(a, n - i - 1, 0);
    }
}

fn main() {
    let mut a = vec![4, 65, 2, -31, 0, 99, 2, 83, 782, 1];
    println!("{}", a.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(" "));
    heapsort(&mut a);
    println!("{}", a.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(" "));
}

