use std::collections::VecDeque;

type DATA = i32;

struct Queue {
    buf: VecDeque<DATA>,
}

impl Queue {
    fn new() -> Self {
        Queue {
            buf: VecDeque::with_capacity(4),
        }
    }

    fn empty(&self) -> bool {
        self.buf.is_empty()
    }

    fn enqueue(&mut self, n: DATA) {
        self.buf.push_back(n);
        if self.buf.capacity() == self.buf.len() {
            self.buf.reserve(self.buf.len());
        }
    }

    fn dequeue(&mut self) -> Option<DATA> {
        self.buf.pop_front()
    }
}

fn main() {
    let mut q = Queue::new();
    q.enqueue(1);
    q.enqueue(2);
    println!("{:?}", q.dequeue()); // Some(1)
    println!("{:?}", q.dequeue()); // Some(2)
    println!("{:?}", q.dequeue()); // None
}

