use std::env;

fn main() {
    let args: Vec<String> = env::args().collect();

    match args.len() {
        1 => println!("Input string : \"\"\nLength : 0\nAll characters are identical."),
        2 => {
            let input = &args[1];
            let len = input.len();
            if len == 1 {
                println!("Input string : \"{}\"\nLength : {}\nAll characters are identical.", input, len);
            } else {
                let reference = input.chars().next().unwrap();
                for (i, c) in input.chars().enumerate().skip(1) {
                    if c != reference {
                        println!("Input string : \"{}\"\nLength : {}\nFirst different character : \"{}\"(0x{:x}) at position : {}", input, len, c, c as u32, i + 1);
                        return;
                    }
                }
                println!("Input string : \"{}\"\nLength : {}\nAll characters are identical.", input, len);
            }
        },
        _ => println!("Usage : {} <Test String>", args[0]),
    }
}

