#include <stdio.h>
#include <string.h>

int cmp(const char *p, const char *q)
{
	while (*p && *q) p = &p[1], q = &q[1];
	return *p;
}

int main()
{
	char line[65536];
	char buf[1000000] = {0};
	char *last = buf;
	char *next = buf;

	while (gets(line)) {
		strcat(line, "\n");
		if (cmp(last, line)) continue;
		if (cmp(line, last)) next = buf;
		last = next;
		strcpy(next, line);
		while (*next) next = &next[1];
	}

	printf("%s", buf);
	return 0;
}

d9357c3b13b31af17141ff46d590ca29.rust_code:
use std::io::{self, BufRead};

fn cmp(p: &[u8], q: &[u8]) -> bool {
    let mut iter_p = p.iter();
    let mut iter_q = q.iter();
    loop {
        match (iter_p.next(), iter_q.next()) {
            (Some(_), Some(_)) => continue,
            _ => return iter_p.next().is_some(),
        }
    }
}

fn main() -> io::Result<()> {
    let stdin = io::stdin();
    let mut buf = String::new();
    let mut last = String::new();
    let mut next = String::new();

    for line in stdin.lock().lines() {
        let mut line = line?;
        line.push('\n');
        if cmp(last.as_bytes(), line.as_bytes()) {
            continue;
        }
        if cmp(line.as_bytes(), last.as_bytes()) {
            next.clear();
        }
        last = next.clone();
        next.push_str(&line);
    }

    print!("{}", next);
    Ok(())
}

