    let mut t = 0;
    while x > 0 {
        t += 1 << ((x % 10) * 6);
        x /= 10;
    }
    t
}

fn fangs(x: XInt, f: &mut [XInt]) -> usize {
    let mut n = 0;
    let nd = ndigits(x);
    if nd % 2 != 0 {
        return 0;
