    let nd = nd / 2;

    let tens: [XInt; 20] = {
        let mut tens = [0; 20];
        tens[0] = 1;
        for i in 1..20 {
            tens[i] = tens[i - 1] * 10;
        }
        tens
    };

    let lo = max(tens[nd - 1], (x + tens[nd] - 2) / (tens[nd] - 1));
    let hi = min(x / lo, (x as f64).sqrt() as XInt);

