fn divisible(n: i32) -> bool {
    let mut p = 1;
    let mut c = n;

    while c > 0 {
        let d = c % 10;
        if d == 0 || n % d != 0 {
            return false;
        }
        p *= d;
        c /= 10;
    }

    n % p == 0
}

