use std::env;

fn main() {
    let args: Vec<String> = env::args().collect();
    let c = args.len();
    assert!(c > 1);

    let n = 1 << (c - 2);
    for i in 0..n {
        if i & (i + (i & -(i as isize) as usize)) != 0 {
            continue;
        }

        for (k, arg) in args.iter().enumerate().skip(1) {
            if i & (1 << (c - k - 2)) != 0 {
                print!("{} ", arg);
            }
        }

        println!();
    }
}

