3db7de663af78b3ba01ce4fc42fc675e.c_code:
#include <stdio.h>

#define twidth 5
#define mdr(rmdr, rmp, n)\
    do { *rmp = 0; _mdr(rmdr, rmp, n); } while (0)

void _mdr(int *rmdr, int *rmp, long long n)
{

    int r = n ? 1 : 0;
    while (n) { 
        r *= (n % 10);
        n /= 10; 
    }

    (*rmp)++;
    if (r >= 10)
        _mdr(rmdr, rmp, r);
    else
        *rmdr = r;
}

int main(void)
{
    int i, j, vmdr, vmp;
    const int values[] = { 123321, 7739, 893, 899998 };
    const int vsize    = sizeof(values) / sizeof(values[0]);


    printf("Number    MDR    MP\n");
    for (i = 0; i < vsize; ++i) {
        mdr(&vmdr, &vmp, values[i]);
        printf("%6d   %3d   %3d\n", values[i], vmdr, vmp);
    }


    int table[10][twidth] = { 0 };
    int tfill[10]         = { 0 };
    int total             = 0;
    for (i = 0; total < 10 * twidth; ++i) {
        mdr(&vmdr, &vmp, i);
        if (tfill[vmdr] < twidth) {
            table[vmdr][tfill[vmdr]++] = i;
            total++;
        }
    }


    printf("\nMDR: [n0..n4]\n");
    for (i = 0; i < 10; ++i) {
        printf("%3d: [", i);
        for (j = 0; j < twidth; ++j)
            printf("%d%s", table[i][j], j != twidth - 1 ? ", " : ""); 
        printf("]\n");
    }

    return 0;
}

3db7de663af78b3ba01ce4fc42fc675e.rust_code:
fn mdr(n: u64) -> (u32, u32) {
    fn _mdr(mut n: u64) -> (u32, u32) {
        let mut r = if n > 0 { 1 } else { 0 };
        while n > 0 {
            r *= (n % 10) as u32;
            n /= 10;
        }
        if r >= 10 {
            let (new_r, mp) = _mdr(r as u64);
            (new_r, mp + 1)
        } else {
            (r, 1)
        }
    }
    _mdr(n)
}

fn main() {
    const VALUES: [u64; 4] = [123321, 7739, 893, 899998];
    println!("Number    MDR    MP");
    for &value in &VALUES {
        let (vmdr, vmp) = mdr(value);
        println!("{:6}   {:3}   {:3}", value, vmdr, vmp);
    }

    const TWIDTH: usize = 5;
    let mut table: [[u64; TWIDTH]; 10] = [[0; TWIDTH]; 10];
    let mut tfill: [usize; 10] = [0; 10];
    let mut total = 0;
    let mut i = 0;
    while total < 10 * TWIDTH {
        let (vmdr, _) = mdr(i);
        if tfill[vmdr as usize] < TWIDTH {
            table[vmdr as usize][tfill[vmdr as usize]] = i;
            tfill[vmdr as usize] += 1;
            total += 1;
