use std::cmp::Ordering;

type Ham = u64;

struct PriorityQueue {
    heap: Vec<Ham>,
}

impl PriorityQueue {
    fn new() -> Self {
        PriorityQueue { heap: Vec::with_capacity(16) }
    }

    fn push(&mut self, h: Ham) {
        let mut i = self.heap.len();
        self.heap.push(h);
        while i > 0 {
            let parent = (i - 1) / 2;
            if self.heap[parent] <= h {
                break;
            }
            self.heap.swap(i, parent);
            i = parent;
        }
    }

    fn pop(&mut self) -> Option<Ham> {
        if self.heap.is_empty() {
            return None;
        }
        let root = self.heap[0];
        let last = self.heap.pop().unwrap();
        if !self.heap.is_empty() {
            self.heap[0] = last;
            self.sift_down(0);
        }
        Some(root)
    }

    fn sift_down(&mut self, mut i: usize) {
        let len = self.heap.len();
        loop {
            let left = 2 * i + 1;
            let right = 2 * i + 2;
            let mut smallest = i;

            if left < len && self.heap[left] < self.heap[smallest] {
                smallest = left;
            }
            if right < len && self.heap[right] < self.heap[smallest] {
                smallest = right;
            }
            if smallest == i {
                break;
            }
            self.heap.swap(i, smallest);
            i = smallest;
        }
    }
}

fn main() {
    let mut pq = PriorityQueue::new();
    pq.push(1);

    for i in 1..=1691 {
        if let Some(h) = pq.pop() {
            pq.push(h * 2);
            pq.push(h * 3);
            pq.push(h * 5);

            if i <= 20 || i == 1691 {
                println!("{:6}: {}", i, h);
            }
        }
    }
}

