            pows[x] = p * pows[x - 1];
            x += 1;
        }

        let mut k = p - 1;
        for n in (p * 2..=top).step_by(p as usize) {
            let mut s = 1 + pows[1];
            k -= 1;

            if k == 0 {
                let mut i = 2;
