#include <stdio.h>
#include <stdint.h>
typedef uint64_t ulong;

int kaprekar(ulong n, int base)
{
	ulong nn = n * n, r, tens = 1;

	if ((nn - n) % (base - 1)) return 0;

	while (tens < n) tens *= base;
	if (n == tens) return 1 == n;

	while ((r = nn % tens) < n) {
		if (nn / tens + r == n) return tens;
		tens *= base;
	}

	return 0;
}

void print_num(ulong n, int base)
{
	ulong q, div = base;

	while (div < n) div *= base;
	while (n && (div /= base)) {
		q = n / div;
		if (q < 10)     putchar(q + '0');
		else            putchar(q + 'a' - 10);
		n -= q * div;
	}
}

int main()
{
	ulong i, tens;
	int cnt = 0;
	int base = 10;

	printf("base 10:\n");
	for (i = 1; i < 1000000; i++)
		if (kaprekar(i, base))
			printf("%3d: %llu\n", ++cnt, i);

	base = 17;
	printf("\nbase %d:\n  1: 1\n", base);
	for (i = 2, cnt = 1; i < 1000000; i++)
		if ((tens = kaprekar(i, base))) {
			printf("%3d: %llu", ++cnt, i);
			printf(" \t"); print_num(i, base);
			printf("\t");  print_num(i * i, base);
			printf("\t");  print_num(i * i / tens, base);
			printf(" + "); print_num(i * i % tens, base);
			printf("\n");
		}

	return 0;
}

6505b877c47dded6f44f6fea43dfcc2e.rust_code:
use std::fmt::Write;

fn kaprekar(n: u64, base: i32) -> u64 {
    let nn = n * n;
    let mut tens = 1;

    if (nn - n) % (base as u64 - 1) != 0 {
        return 0;
    }

    while tens < n {
        tens *= base as u64;
    }
    if n == tens {
        return if n == 1 { 1 } else { 0 };
    }

    while let r @ 0.. = nn % tens {
        if nn / tens + r == n {
            return tens;
        }
        tens *= base as u64;
    }

    0
}

fn print_num(mut n: u64, base: i32) {
    let mut div = base as u64;
    while div < n {
        div *= base as u64;
    }
    let mut buffer = String::new();
    while n > 0 && div > 1 {
        div /= base as u64;
        let q = n / div;
        if q < 10 {
            write!(buffer, "{}", q).unwrap();
        } else {
            write!(buffer, "{}", (b'a' + (q - 10) as u8) as char).unwrap();
        }
        n -= q * div;
    }
    print!("{}", buffer);
}

fn main() {
    let mut cnt = 0;
    let base = 10;

    println!("base 10:");
    for i in 1..1_000_000 {
        if kaprekar(i, base) != 0 {
            cnt += 1;
            println!("{:3}: {}", cnt, i);
        }
    }

    let base = 17;
    println!("\nbase {}:\n  1: 1", base);
    cnt = 1;
    for i in 2..1_000_000 {
        if let tens @ 1.. = kaprekar(i, base) {
            cnt += 1;
            print!("{:3}: {}", cnt, i);
            print!("\t");
            print_num(i, base);
            print!("\t");
            print_num(i * i, base);
            print!("\t");
            print_num(i * i / tens, base);
            print!(" + ");
            print_num(i * i % tens, base);
            println!();
        }
    }
}

