#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PRIME 1000000
char *primes;
int n_primes;


void init_primes()
{
	int j;
	primes = malloc(sizeof(char) * MAX_PRIME);
	memset(primes, 1, MAX_PRIME);
	primes[0] = primes[1] = 0;
	int i = 2;
	while (i * i < MAX_PRIME) {
		for (j = i * 2; j < MAX_PRIME; j += i)
			primes[j] = 0;
		while (++i < MAX_PRIME && !primes[i]);
	}
}

int left_trunc(int n)
{
	int tens = 1;
	while (tens < n) tens *= 10;

	while (n) {
		if (!primes[n]) return 0;
		tens /= 10;
		if (n < tens) return 0;
		n %= tens;
	}
	return 1;
}

int right_trunc(int n)
{
	while (n) {
		if (!primes[n]) return 0;
		n /= 10;
	}
	return 1;
}

int main()
{
	int n;
	int max_left = 0, max_right = 0;
	init_primes();

	for (n = MAX_PRIME - 1; !max_left;  n -= 2)
		if (left_trunc(n)) max_left = n;

	for (n = MAX_PRIME - 1; !max_right; n -= 2)
		if (right_trunc(n)) max_right = n;

	printf("Left: %d; right: %d\n", max_left, max_right);
	return 0;
}

1db159cfd87c09539ceb80d22a7d50a4.rust_code:
const MAX_PRIME: usize = 1_000_000;

fn init_primes() -> Vec<bool> {
    let mut primes = vec![true; MAX_PRIME];
    primes[0] = false;
    primes[1] = false;
    let mut i = 2;
    while i * i < MAX_PRIME {
        if primes[i] {
            for j in (i * 2..MAX_PRIME).step_by(i) {
                primes[j] = false;
            }
        }
        i += 1;
        while i < MAX_PRIME && !primes[i] {
            i += 1;
        }
    }
    primes
}

fn left_trunc(mut n: usize, primes: &[bool]) -> bool {
    let mut tens = 1;
    while tens < n {
        tens *= 10;
    }

    while n > 0 {
        if !primes[n] {
            return false;
        }
        tens /= 10;
        if n < tens {
            return false;
        }
        n %= tens;
    }
    true
}

fn right_trunc(mut n: usize, primes: &[bool]) -> bool {
    while n > 0 {
        if !primes[n] {
            return false;
        }
        n /= 10;
    }
    true
}

fn main() {
    let primes = init_primes();
    let mut max_left = None;
    let mut max_right = None;

    for n in (3..MAX_PRIME).rev().step_by(2) {
        if max_left.is_none() && left_trunc(n, &primes) {
            max_left = Some(n);
        }
        if max_right.is_none() && right_trunc(n, &primes) {
            max_right = Some(n);
        }
        if max_left.is_some() && max_right.is_some() {
            break;
        }
    }

    if let (Some(left), Some(right)) = (max_left, max_right) {
        println!("Left: {}; right: {}", left, right);
    }
}

