    let col = pos % 9;

    for i in 0..9 {
        used |= 1 << (grid[i * 9 + col] - 1);
    }

    for j in 0..9 {
        used |= 1 << (grid[row * 9 + j] - 1);
    }

    let box_row = (row / 3) * 3;
    let box_col = (col / 3) * 3;
    for i in box_row..box_row + 3 {
        for j in box_col..box_col + 3 {
            used |= 1 << (grid[i * 9 + j] - 1);
        }
    }

    for num in 1..=9 {
