use std::env;
use std::process;

fn solve(n: usize, col: usize, hist: &mut Vec<usize>, count: &mut usize) {
    if col == n {
        *count += 1;
        println!("\nNo. {}\n-----", count);
        for i in 0..n {
            for j in 0..n {
                print!("{}", if j == hist[i] { 'Q' } else if (i + j) % 2 == 1 { ' ' } else { '.' });
            }
            println!();
        }
        return;
    }

    for i in 0..n {
        if (0..col).any(|j| hist[j] == i || (hist[j] as isize - i as isize).abs() == col as isize - j as isize) {
            continue;
        }

        hist[col] = i;
        solve(n, col + 1, hist, count);
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let n: usize = match args.get(1) {
        Some(arg) => arg.parse().unwrap_or(8),
        None => 8,
    };

    if n <= 1 {
        process::exit(1);
    }

    let mut hist = vec![0; n];
    let mut count = 0;
    solve(n, 0, &mut hist, &mut count);
}

