use std::cmp::Ordering;

fn perm_sort<T, F>(arr: &mut [T], mut _cmp: F)
where
    T: Clone,
    F: Fn(&T, &T) -> Ordering,
{
    let mut tmp = arr[0].clone();
    let n = arr.len();

    loop {
        let mut p = n - 1;
        while p > 0 {
            if _cmp(&arr[p - 1], &arr[p]) == Ordering::Greater {
                break;
            }
            p -= 1;
        }

        if p == 0 {
            break;
        }

        let mut q = n - 1;
        while q > p {
            if _cmp(&arr[p - 1], &arr[q]) == Ordering::Greater {
                break;
            }
            q -= 1;
        }

        arr.swap(p - 1, q);

        let (mut left, mut right) = (p, n - 1);
        while left < right {
            arr.swap(left, right);
            left += 1;
            right -= 1;
        }
    }
}

fn scmp(a: &&str, b: &&str) -> Ordering {
    a.cmp(b)
}

fn main() {
    let mut strs = vec!["spqr", "abc", "giant squid", "stuff", "def"];
    perm_sort(&mut strs, scmp);

    for s in strs {
        println!("{}", s);
    }
}

