    io::stdout().flush().unwrap();
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let depth = if args.len() > 1 { args[1].parse::<i32>().unwrap_or(10) } else { 10 };
    let size = 1 << depth;

    eprintln!("size: {} depth: {}", size, depth);
    sierp(size, depth + 2);
}

