#include<stdlib.h>
#include<stdio.h>

int *
anynacci (int *seedArray, int howMany)
{
  int *result = malloc (howMany * sizeof (int));
  int i, j, initialCardinality;

  for (i = 0; seedArray[i] != 0; i++);
  initialCardinality = i;

  for (i = 0; i < initialCardinality; i++)
    result[i] = seedArray[i];

  for (i = initialCardinality; i < howMany; i++)
    {
      result[i] = 0;
      for (j = i - initialCardinality; j < i; j++)
        result[i] += result[j];
    }
  return result;
}

int
main ()
{
  int fibo[] = { 1, 1, 0 }, tribo[] = { 1, 1, 2, 0 }, tetra[] = { 1, 1, 2, 4, 0 }, luca[] = { 2, 1, 0 };
  int *fibonacci = anynacci (fibo, 10), *tribonacci = anynacci (tribo, 10), *tetranacci = anynacci (tetra, 10), 
      *lucas = anynacci(luca, 10);
  int i;

  printf ("\nFibonacci\tTribonacci\tTetranacci\tLucas\n");

  for (i = 0; i < 10; i++)
    printf ("\n%d\t\t%d\t\t%d\t\t%d", fibonacci[i], tribonacci[i],
            tetranacci[i], lucas[i]);

  return 0;
}

408a318e7909501cbc649359883d994a.rust_code:
fn anynacci(seed_array: &[i32], how_many: usize) -> Vec<i32> {
    let mut result = vec![0; how_many];
    let initial_cardinality = seed_array.iter().position(|&x| x == 0).unwrap_or(seed_array.len());

    result[..initial_cardinality].copy_from_slice(&seed_array[..initial_cardinality]);

    for i in initial_cardinality..how_many {
        result[i] = result[(i - initial_cardinality)..i].iter().sum();
    }

    result
}

fn main() {
    let fibo = [1, 1, 0];
    let tribo = [1, 1, 2, 0];
    let tetra = [1, 1, 2, 4, 0];
    let luca = [2, 1, 0];

    let fibonacci = anynacci(&fibo, 10);
    let tribonacci = anynacci(&tribo, 10);
    let tetranacci = anynacci(&tetra, 10);
    let lucas = anynacci(&luca, 10);

    println!("\nFibonacci\tTribonacci\tTetranacci\tLucas\n");

    for i in 0..10 {
        println!(
            "\n{}\t\t{}\t\t{}\t\t{}",
            fibonacci[i], tribonacci[i], tetranacci[i], lucas[i]
        );
    }
}

