use std::cmp;

#[derive(Debug)]
struct Item {
    name: &'static str,
    value: f64,
    weight: f64,
    volume: f64,
}

fn knapsack(items: &[Item], i: usize, value: f64, weight: f64, volume: f64, count: &mut [usize], best: &mut [usize], best_value: &mut f64) {
    if i == items.len() {
        if value > *best_value {
            *best_value = value;
            best.copy_from_slice(count);
        }
        return;
    }
    let m1 = (weight / items[i].weight).floor() as usize;
    let m2 = (volume / items[i].volume).floor() as usize;
    let m = cmp::min(m1, m2);
    for j in (0..=m).rev() {
        count[i] = j;
        knapsack(items, i + 1, value + j as f64 * items[i].value, weight - j as f64 * items[i].weight, volume - j as f64 * items[i].volume, count, best, best_value);
    }
}

fn main() {
    let items = [
        Item { name: "panacea", value: 3000.0, weight: 0.3, volume: 0.025 },
        Item { name: "ichor", value: 1800.0, weight: 0.2, volume: 0.015 },
        Item { name: "gold", value: 2500.0, weight: 2.0, volume: 0.002 },
    ];
    let n = items.len();
    let mut count = vec![0; n];
    let mut best = vec![0; n];
    let mut best_value = 0.0;
    knapsack(&items, 0, 0.0, 25.0, 0.25, &mut count, &mut best, &mut best_value);
    for (i, &item_count) in best.iter().enumerate() {
        println!("{} {}", item_count, items[i].name);
    }
    println!("best value: {:.0}", best_value);
}

