use std::fmt::Write;

type Int64 = i64;

fn to_word(ws: &mut String, w: Int64) {
    write!(ws, "W{:05}", w).unwrap();
}

fn from_word(ws: &str) -> Int64 {
    ws[1..].parse().unwrap()
}

fn main() {
    let mut w1s = String::with_capacity(7);
    let mut w2s = String::with_capacity(7);
    let mut w3s = String::with_capacity(7);

    let lat = 28.3852;
    let lon = -81.5638;
    println!("Starting figures:");
    println!("  latitude = {:.4}, longitude = {:.4}", lat, lon);

    let ilat = (lat * 10000.0 + 900000.0) as Int64;
    let ilon = (lon * 10000.0 + 1800000.0) as Int64;

    let latlon = (ilat << 22) + ilon;

    let w1 = (latlon >> 28) & 0x7fff;
    let w2 = (latlon >> 14) & 0x3fff;
    let w3 = latlon & 0x3fff;

    to_word(&mut w1s, w1);
    to_word(&mut w2s, w2);
    to_word(&mut w3s, w3);

    println!("\nThree word location is:");
    println!("  {} {} {}", w1s, w2s, w3s);

    let w1 = from_word(&w1s);
    let w2 = from_word(&w2s);
    let w3 = from_word(&w3s);

    let latlon = (w1 << 28) | (w2 << 14) | w3;
    let ilat = latlon >> 22;
    let ilon = latlon & 0x3fffff;
    let lat = (ilat - 900000) as f64 / 10000.0;
    let lon = (ilon - 1800000) as f64 / 10000.0;

    println!("\nAfter reversing the procedure:");
    println!("  latitude = {:.4}, longitude = {:.4}", lat, lon);
}

