        let mut x = 1;
        while pows[x - 1] <= top / p {
            pows[x] = p * pows[x - 1];
            x += 1;
        }

        let mut k = p - 1;
        for n in (p * 2..=top).step_by(p as usize) {
            let mut s = 1 + pows[1];
            k -= 1;

            if k == 0 {
                let mut i = 2;
                while i < x && n % pows[i] == 0 {
                    s += pows[i];
                    i += 1;
                }
                k = p;
            }
            divsum[n as usize] *= s;
        }
    }

    for p in ((top / 2) + 1)..=top {
        if divsum[p as usize] > 1 {
            divsum[p as usize] -= p;
        }
    }

