        Some(m) if m > 0 => m,
        _ => 5,
    };

    let mut s = vec![0; m * m];

    for i in 0..(m * 2) {
        for j in if i < m { 0 } else { i - m + 1 }..=i.min(m - 1) {
            let index = if i & 1 == 1 {
                j * (m - 1) + i
            } else {
                (i - j) * m + j
            };
            s[index] = i * m + j - if i >= m { (i - m + 1) * m } else { 0 };
        }
    }

    for (i, &value) in s.iter().enumerate() {
        print!("{:3}", value);
        if (i + 1) % m == 0 {
            println!();
        } else {
            print!(" ");
        }
    }
}

