use std::env;

fn main() {
    let args: Vec<String> = env::args().collect();
    let m = match args.get(1).and_then(|s| s.parse::<usize>().ok()) {
        Some(m) if m > 0 => m,
        _ => 5,
    };

    let mut s = vec![0; m * m];

    for (i, row) in (0..m * 2).enumerate() {
        let start = if row < m { 0 } else { row - m + 1 };
        let end = usize::min(row + 1, m);
        for (j, n) in (start..end).enumerate() {
            let index = if row & 1 == 1 {
                j * (m - 1) + row
            } else {
                (row - j) * m + j
            };
            s[index] = i * (end - start) + j;
        }
    }

    for (i, &value) in s.iter().enumerate() {
        print!("{:3}", value);
        if (i + 1) % m == 0 {
            println!();
        } else {
            print!(" ");
        }
    }
}

