    while x > 0 {
        t += 1 << ((x % 10) * 6);
        x /= 10;
    }
    t
}

fn fangs(x: XInt, f: &mut [XInt]) -> usize {
    let mut n = 0;
    let nd = ndigits(x);
    if nd % 2 != 0 {
        return 0;
    }
    let nd = nd / 2;

    let tens: [XInt; 20] = {
        let mut tens = [0; 20];
        tens[0] = 1;
        for i in 1..20 {
            tens[i] = tens[i - 1] * 10;
        }
        tens
    };

    let lo = max(tens[nd - 1], (x + tens[nd] - 2) / (tens[nd] - 1));
    let hi = min(x / lo, (x as f64).sqrt() as XInt);

    let t = dtally(x);
    for a in lo..=hi {
        let b = x / a;
        if a * b == x && (a % 10 != 0 || b % 10 != 0) && t == dtally(a) + dtally(b) {
