        let j = fangs(x, &mut f);
        if j == 0 {
            continue;
        }
        n += 1;
        print!("{:2}: ", n);
        show_fangs(x, &f, j);
        if n >= 25 {
            break;
        }
    }

    println!();
    for &x in &bigs[..bigs.len() - 1] {
        let j = fangs(x, &mut f);
        if j > 0 {
            show_fangs(x, &f, j);
        } else {
            println!("{} is not vampiric", x);
        }
    }
}

