    while div < n {
        div *= base as u64;
    }
    let mut buffer = String::new();
    while n > 0 && div > 1 {
        div /= base as u64;
        let q = n / div;
        if q < 10 {
            write!(buffer, "{}", q).unwrap();
        } else {
            write!(buffer, "{}", (b'a' + (q - 10) as u8) as char).unwrap();
        }
        n -= q * div;
    }
    print!("{}", buffer);
}

