    let mut pq = PriorityQueue::new();
    pq.push(1);

    for i in 1..=1691 {
        if let Some(h) = pq.pop() {
            pq.push(h * 2);
            pq.push(h * 3);
            pq.push(h * 5);

            if i <= 20 || i == 1691 {
                println!("{:6}: {}", i, h);
            }
        }
    }
}

