fn gcd(mut m: i32, mut n: i32) -> i32 {
    while m != 0 {
        let tmp = m;
        m = n % m;
        n = tmp;
    }
    n
}

fn lcm(m: i32, n: i32) -> i32 {
    m / gcd(m, n) * n
}

fn main() {
    println!("lcm(35, 21) = {}", lcm(21, 35));
}

