use std::cmp::Ordering;

#[derive(Debug, Clone, Copy)]
struct Point {
    x: i32,
    y: i32,
}

fn ccw(a: &Point, b: &Point, c: &Point) -> bool {
    (b.x - a.x) * (c.y - a.y) > (b.y - a.y) * (c.x - a.x)
}

impl Ord for Point {
    fn cmp(&self, other: &Self) -> Ordering {
        self.x.cmp(&other.x).then_with(|| self.y.cmp(&other.y))
    }
}

impl PartialOrd for Point {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl PartialEq for Point {
    fn eq(&self, other: &Self) -> bool {
        self.x == other.x && self.y == other.y
    }
}

impl Eq for Point {}

fn print_points(points: &[Point]) {
    print!("[");
    if let Some((first, rest)) = points.split_first() {
        print!("({},{})", first.x, first.y);
        for point in rest {
            print!(", ({},{})", point.x, point.y);
        }
    }
    println!("]");
}

fn convex_hull(mut points: Vec<Point>) -> Vec<Point> {
    if points.is_empty() {
        return vec![];
    }

    points.sort();

    let mut hull = Vec::with_capacity(points.len());

    for &point in &points {
        while hull.len() >= 2 && !ccw(&hull[hull.len() - 2], &hull[hull.len() - 1], &point) {
            hull.pop();
        }
        hull.push(point);
    }

    let t = hull.len();
    for &point in points.iter().rev().skip(1) {
        while hull.len() >= t && !ccw(&hull[hull.len() - 2], &hull[hull.len() - 1], &point) {
            hull.pop();
        }
        hull.push(point);
    }

    hull.pop(); // Remove the last point which is the same as the first

    hull
}

fn main() {
    let points = vec![
        Point { x: 16, y: 3 }, Point { x: 12, y: 17 }, Point { x: 0, y: 6 }, Point { x: -4, y: -6 }, Point { x: 16, y: 6 },
        Point { x: 16, y: -7 }, Point { x: 16, y: -3 }, Point { x: 17, y: -4 }, Point { x: 5, y: 19 }, Point { x: 19, y: -8 },
        Point { x: 3, y: 16 }, Point { x: 12, y: 13 }, Point { x: 3, y: -4 }, Point { x: 17, y: 5 }, Point { x: -3, y: 15 },
        Point { x: -3, y: -9 }, Point { x: 0, y: 11 }, Point { x: -9, y: -3 }, Point { x: -4, y: -2 }, Point { x: 12, y: 10 }
    ];

    let hull = convex_hull(points);
    println!("Convex Hull: ");
    print_points(&hull);
}

