use std::f64;

fn divisor_count(mut n: u32) -> u32 {
    let mut total = 1;

    while n & 1 == 0 {
        n >>= 1;
        total += 1;
    }

    let mut p = 3;
    while p * p <= n {
        let mut count = 1;
        while n % p == 0 {
            n /= p;
            count += 1;
        }
        total *= count;
        p += 2;
    }

    if n > 1 {
        total *= 2;
    }
    total
}

fn divisor_product(n: u32) -> f64 {
    (n as f64).powf(divisor_count(n) as f64 / 2.0)
}

fn main() {
    const LIMIT: u32 = 50;
    println!("Product of divisors for the first {} positive integers:", LIMIT);
    for n in 1..=LIMIT {
        print!("{:11}", divisor_product(n));
        if n % 5 == 0 {
            println!();
        }
    }
}

