fn divisor_count(mut n: u32) -> u32 {
    let mut total = 1;

    while n & 1 == 0 {
        n >>= 1;
        total += 1;
    }

    let mut p = 3;
    while p * p <= n {
        let mut count = 1;
        while n % p == 0 {
            n /= p;
            count += 1;
        }
        total *= count;
        p += 2;
    }

    if n > 1 {
        total *= 2;
    }
    total
}

fn divisor_product(n: u32) -> f64 {
    (n as f64).powf(divisor_count(n) as f64 / 2.0)
}

