#include <stdio.h>

int droot(long long int x, int base, int *pers)
{
	int d = 0;
	if (pers)
		for (*pers = 0; x >= base; x = d, (*pers)++)
			for (d = 0; x; d += x % base, x /= base);
	else if (x && !(d = x % (base - 1)))
			d = base - 1;

	return d;
}

int main(void)
{
	int i, d, pers;
	long long x[] = {627615, 39390, 588225, 393900588225LL};

	for (i = 0; i < 4; i++) {
		d = droot(x[i], 10, &pers);
		printf("%lld: pers %d, root %d\n", x[i], pers, d);
	}

	return 0;
}

98545d2c804aae78b7566326b4bb1f28.rust_code:
fn droot(mut x: u64, base: u32, pers: &mut Option<usize>) -> u32 {
    let mut d = 0;
    if let Some(p) = pers {
        *p = 0;
        while x >= base as u64 {
            d = 0;
            let mut temp = x;
            while temp > 0 {
                d += (temp % base as u64) as u32;
                temp /= base as u64;
            }
            x = d as u64;
            *p += 1;
        }
    } else if x != 0 && x % (base as u64 - 1) == 0 {
        d = base - 1;
    }

    d
}

fn main() {
    let numbers = [627615, 39390, 588225, 393900588225];
    for &num in &numbers {
        let mut pers = None;
        let root = droot(num, 10, &mut pers);
        println!("{}: pers {:?}, root {}", num, pers, root);
    }
}

