fn droot(mut x: u64, base: u32, pers: &mut Option<usize>) -> u32 {
    let mut d = 0;
    if let Some(p) = pers {
        *p = 0;
        while x >= base as u64 {
            d = 0;
            let mut temp = x;
            while temp > 0 {
                d += (temp % base as u64) as u32;
                temp /= base as u64;
            }
            x = d as u64;
            *p += 1;
        }
    } else if x != 0 && x % (base as u64 - 1) == 0 {
        d = base - 1;
    }

    d
}

fn main() {
    let numbers = [627615, 39390, 588225, 393900588225];
    for &num in &numbers {
        let mut pers = None;
        let root = droot(num, 10, &mut pers);
        println!("{}: pers {:?}, root {}", num, pers, root);
    }
}

