fn bsearch(a: &[i32], x: i32) -> Option<usize> {
    let mut i = 0;
    let mut j = a.len().wrapping_sub(1);
    while i <= j {
        let k = i + (j - i) / 2;
        match a[k].cmp(&x) {
            std::cmp::Ordering::Equal => return Some(k),
            std::cmp::Ordering::Less => i = k + 1,
            std::cmp::Ordering::Greater => j = k.wrapping_sub(1),
        }
    }
    None
}

