fn mertens_numbers(max: usize) -> Vec<i32> {
    let mut m = vec![0; max + 1];
    m[1] = 1;
    for n in 2..=max {
        m[n] = 1;
        for k in 2..=n {
            m[n] -= m[n / k];
        }
    }
    m
}

fn main() {
    const MAX: usize = 1000;
    let mertens = mertens_numbers(MAX);

    println!("First 199 Mertens numbers:");
    let count = 200;
    let mut column = 0;
    for &value in &mertens[0..count] {
        if column > 0 {
            print!(" ");
        }
        if column == 0 {
            print!("  ");
        } else {
            print!("{:2}", value);
        }
        column += 1;
        if column == 20 {
            println!();
            column = 0;
        }
    }

    let mut zero = 0;
    let mut cross = 0;
    let mut previous = 0;
    for &m in &mertens[1..=MAX] {
        if m == 0 {
            zero += 1;
            if previous != 0 {
                cross += 1;
            }
        }
        previous = m;
    }

    println!("M(n) is zero {} times for 1 <= n <= {}.", zero, MAX);
    println!("M(n) crosses zero {} times for 1 <= n <= {}.", cross, MAX);
}

