}

fn is_curzon(n: u64, k: u64) -> bool {
    let r = k * n;
    mod_pow(k, n, r + 1) == r
}

fn main() {
    for k in (2..=10).step_by(2) {
        println!("Curzon numbers with base {}: ", k);
        let mut count = 0;
        let mut n = 1;
        while count < 50 {
            if is_curzon(n, k) {
                print!("{:>4} ", n);
                count += 1;
                if count % 10 == 0 {
                    println!();
                }
            }
            n += 1;
        }
        while count < 1000 {
            if is_curzon(n, k) {
                count += 1;
            }
            n += 1;
        }
        println!("1,000th Curzon number with base {}: {:>4}", k, n - 1);
        println!();
    }
}

